    _base={"__name__":"_gui_core"}
    exec(compile('# -*- coding: utf-8 -*-\n"""Public DOSY v3: acquisition only after explicit user confirmation."""\nfrom __future__ import unicode_literals\nimport sys, types\n_base = {"__name__": "_dosy_v2_embedded"}\nexec(compile(\'# -*- coding: utf-8 -*-\\n"""Public DOSY console, Jython 2.7. See docs/en/bruker-step-by-step.md for scope."""\\nfrom __future__ import print_function, unicode_literals\\nimport sys, types, json\\ndef _load_module(name, source):\\n    module = types.ModuleType(name)\\n    sys.modules[name] = module\\n    exec(compile(source.encode("utf-8"), name + ".py", "exec"), module.__dict__)\\n    return module\\n_load_module(\\\'_dosy_ramp_engine\\\', \\\'# -*- coding: utf-8 -*-\\\\nfrom __future__ import print_function, unicode_literals\\\\nimport json, math, os, re\\\\nfrom decimal import Decimal, InvalidOperation\\\\ntry:\\\\n    string_types = (basestring,)\\\\n    text_type = unicode\\\\nexcept NameError:\\\\n    string_types = (str,)\\\\n    text_type = str\\\\n\\\\nDEFAULT_CONFIG = {\\\\n    "schema_version": 1,\\\\n    "template_expno": 10,\\\\n    "template_procno": 1,\\\\n    "expected_dataset_name": "",\\\\n    "expected_pulse_program": "",\\\\n    "ramp_count": 3,\\\\n    "start_expno": 100,\\\\n    "experiment_stride": 100,\\\\n    "gradient_index": 6,\\\\n    "gradient_start_percent": 8,\\\\n    "gradient_stop_percent": 96,\\\\n    "gradient_step_percent": 4,\\\\n    "delay_parameter": None,\\\\n    "delay_values_s": None,\\\\n    "delay_mapping_confirmed": False,\\\\n    "pulse_parameter": None,\\\\n    "pulse_value_us": None,\\\\n    "pulse_mapping_confirmed": False,\\\\n    "dummy_scans": 16,\\\\n    "example_only": False,\\\\n}\\\\n\\\\n\\\\nclass PlanError(ValueError):\\\\n    pass\\\\n\\\\n\\\\ndef integer(value, name, minimum=1, maximum=2147483647):\\\\n    if isinstance(value, bool):\\\\n        raise PlanError("%s debe ser entero." % name)\\\\n    try:\\\\n        parsed = int(value)\\\\n    except (ValueError, TypeError, OverflowError):\\\\n        raise PlanError("%s debe ser entero." % name)\\\\n    if text_type(parsed) != text_type(value) and parsed != value:\\\\n        raise PlanError("%s debe ser entero." % name)\\\\n    if not minimum <= parsed <= maximum:\\\\n        raise PlanError("%s debe estar entre %s y %s." % (name, minimum, maximum))\\\\n    return parsed\\\\n\\\\n\\\\ndef number(value, name, positive=False):\\\\n    if isinstance(value, bool):\\\\n        raise PlanError("%s debe ser num\\\\xe9rico." % name)\\\\n    try:\\\\n        parsed = float(value)\\\\n    except (ValueError, TypeError, OverflowError):\\\\n        raise PlanError("%s debe ser num\\\\xe9rico." % name)\\\\n    if not (not math.isnan(parsed) and not math.isinf(parsed)) or (positive and parsed <= 0):\\\\n        raise PlanError("%s debe ser finito%s." % (name, " y mayor que cero" if positive else ""))\\\\n    return parsed\\\\n\\\\n\\\\ndef param_name(value, prefix):\\\\n    if not isinstance(value, string_types) or not re.match(prefix + r"\\\\\\\\d{1,3}$", value.upper().replace(" ", "")):\\\\n        raise PlanError("Par\\\\xe1metro inv\\\\xe1lido: use %s seguido de un \\\\xedndice, p. ej. %s." % (prefix, "D20" if prefix == "D" else "P30"))\\\\n    return value.upper().replace(" ", "")\\\\n\\\\n\\\\ndef format_number(value):\\\\n    return format(float(value), ".12g")\\\\n\\\\n\\\\ndef gradient_values(config):\\\\n    try:\\\\n        first = Decimal(text_type(config["gradient_start_percent"]))\\\\n        last = Decimal(text_type(config["gradient_stop_percent"]))\\\\n        step = Decimal(text_type(config["gradient_step_percent"]))\\\\n    except (InvalidOperation, ValueError):\\\\n        raise PlanError("Los gradientes deben ser n\\\\xfameros.")\\\\n    if not all(x.is_finite() for x in (first, last, step)):\\\\n        raise PlanError("Los gradientes deben ser finitos.")\\\\n    if not 0 <= first < last <= 100 or step <= 0:\\\\n        raise PlanError("Requiere 0 <= inicio < final <= 100 y paso positivo.")\\\\n    count = (last - first) / step\\\\n    if count != count.to_integral_value():\\\\n        raise PlanError("El paso no alcanza exactamente el gradiente final.")\\\\n    if count + 1 > 10000:\\\\n        raise PlanError("Demasiados puntos de gradiente (m\\\\xe1ximo 10000).")\\\\n    return [float(first + i * step) for i in range(int(count) + 1)]\\\\n\\\\n\\\\ndef build_plan(given=None):\\\\n    config = dict(DEFAULT_CONFIG)\\\\n    if given:\\\\n        unknown = set(given) - set(config)\\\\n        if unknown:\\\\n            raise PlanError("Opciones desconocidas: " + ", ".join(sorted(unknown)))\\\\n        config.update(given)\\\\n    if config["schema_version"] != 1:\\\\n        raise PlanError("schema_version debe ser 1.")\\\\n    for key in ("example_only", "delay_mapping_confirmed", "pulse_mapping_confirmed"):\\\\n        if not isinstance(config[key], bool):\\\\n            raise PlanError(key + " debe ser true o false.")\\\\n    for key in ("template_expno", "template_procno", "ramp_count", "start_expno", "experiment_stride"):\\\\n        config[key] = integer(config[key], key)\\\\n    config["gradient_index"] = integer(config["gradient_index"], "gradient_index", 0, 99)\\\\n    if config["ramp_count"] > 100:\\\\n        raise PlanError("M\\\\xe1ximo 100 rampas por plan.")\\\\n    for key in ("expected_dataset_name", "expected_pulse_program"):\\\\n        if not isinstance(config[key], string_types) or any(c in config[key] for c in ("/", "\\\\\\\\\\\\\\\\", "\\\\\\\\n", "\\\\\\\\r", "\\\\\\\\0")):\\\\n            raise PlanError(key + " debe ser un nombre simple sin rutas.")\\\\n    values = gradient_values(config)\\\\n    if config["ramp_count"] > 1 and config["experiment_stride"] < len(values):\\\\n        raise PlanError("experiment_stride provoca solapamiento entre rampas.")\\\\n    delay_values = config["delay_values_s"]\\\\n    if delay_values is not None:\\\\n        if not isinstance(delay_values, list) or len(delay_values) != config["ramp_count"]:\\\\n            raise PlanError("delay_values_s debe contener un valor por rampa.")\\\\n        config["delay_parameter"] = param_name(config["delay_parameter"], "D")\\\\n        delay_values = [number(v, "delay_values_s", positive=True) for v in delay_values]\\\\n        config["delay_values_s"] = delay_values\\\\n        if not config["example_only"] and not config["delay_mapping_confirmed"]:\\\\n            raise PlanError("Confirme en la secuencia la correspondencia del par\\\\xe1metro D con el tiempo de difusi\\\\xf3n, o use example_only.")\\\\n    elif config["delay_parameter"] is not None:\\\\n        raise PlanError("delay_parameter requiere delay_values_s.")\\\\n    if config["pulse_value_us"] is not None:\\\\n        config["pulse_parameter"] = param_name(config["pulse_parameter"], "P")\\\\n        config["pulse_value_us"] = number(config["pulse_value_us"], "pulse_value_us", positive=True)\\\\n        if not config["example_only"] and not config["pulse_mapping_confirmed"]:\\\\n            raise PlanError("Confirme en la secuencia la funci\\\\xf3n del par\\\\xe1metro P, o use example_only.")\\\\n    elif config["pulse_parameter"] is not None:\\\\n        raise PlanError("pulse_parameter requiere pulse_value_us.")\\\\n    if (delay_values or config["pulse_value_us"] is not None) and not config["expected_pulse_program"] and not config["example_only"]:\\\\n        raise PlanError("Para modificar D/P indique expected_pulse_program y verifique su correspondencia.")\\\\n    if config["dummy_scans"] is not None:\\\\n        config["dummy_scans"] = integer(config["dummy_scans"], "dummy_scans", 0, 1000000)\\\\n    rows = []\\\\n    for ramp in range(config["ramp_count"]):\\\\n        for index, gradient in enumerate(values):\\\\n            expno = config["start_expno"] + ramp * config["experiment_stride"] + index\\\\n            integer(expno, "EXPNO calculado")\\\\n            if expno == config["template_expno"]:\\\\n                raise PlanError("La plantilla EXPNO %s coincide con un destino." % expno)\\\\n            rows.append({\\\\n                "ramp": ramp + 1,\\\\n                "point": index + 1,\\\\n                "expno": expno,\\\\n                "procno": config["template_procno"],\\\\n                "gradient_index": config["gradient_index"],\\\\n                "gradient_percent": gradient,\\\\n                "delay_parameter": config["delay_parameter"],\\\\n                "delay_s": None if delay_values is None else delay_values[ramp],\\\\n                "pulse_parameter": config["pulse_parameter"],\\\\n                "pulse_us": config["pulse_value_us"],\\\\n                "dummy_scans": config["dummy_scans"],\\\\n            })\\\\n    if len(set(row["expno"] for row in rows)) != len(rows):\\\\n        raise PlanError("Se han detectado EXPNO duplicados.")\\\\n    return {\\\\n        "schema_version": 1,\\\\n        "generator": "DiffAtOnce workshop offline ramp generator 1.0",\\\\n        "example_only": config["example_only"],\\\\n        "can_prepare": not config["example_only"],\\\\n        "purpose": "Preparaci\\\\xf3n de par\\\\xe1metros; no adquisici\\\\xf3n, calibraci\\\\xf3n ni c\\\\xe1lculo de b.",\\\\n        "gradient_unit": "porcentaje GPZ; no G/cm ni T/m",\\\\n        "delay_unit": "s (unidad del par\\\\xe1metro TopSpin D)",\\\\n        "pulse_unit": "us (unidad del par\\\\xe1metro TopSpin P; no asumir delta=P)",\\\\n        "config": config,\\\\n        "points_per_ramp": len(values),\\\\n        "experiment_count": len(rows),\\\\n        "rows": rows,\\\\n    }\\\\n\\\\n\\\\ndef parameter_key(name):\\\\n    # TopSpin Python usa "D 20" / "P 30" / "GPZ 6".\\\\n    return name[0] + " " + name[1:]\\\\n\\\\n\\\\ndef finite_number(value):\\\\n    result = float(value)\\\\n    if math.isnan(result) or math.isinf(result):\\\\n        raise RuntimeError("Valor numerico no finito.")\\\\n    return result\\\\n\\\\n\\\\ndef format_value(value):\\\\n    return "%.12g" % float(value)\\\\n\\\\n\\\\ndef equivalent_dataset(left, right):\\\\n    return (text_type(left[0]) == text_type(right[0]) and\\\\n            text_type(left[1]) == text_type(right[1]) and\\\\n            text_type(left[2]) == text_type(right[2]) and\\\\n            os.path.normcase(os.path.realpath(text_type(left[3]))) ==\\\\n            os.path.normcase(os.path.realpath(text_type(right[3]))))\\\\n\\\\n\\\\ndef is_signal_file(name):\\\\n    if name in ("fid", "ser"):\\\\n        return True\\\\n    # Nombres Bruker de datos numericos procesados 1r/1i, 2rr/2ri, 3rrr...\\\\n    return len(name) >= 2 and name[0] in "12345678" and set(name[1:]).issubset(set("ri"))\\\\n\\\\n\\\\ndef ensure_parameter_only(path):\\\\n    for folder, dirs, files in os.walk(path):\\\\n        for name in files:\\\\n            if is_signal_file(name):\\\\n                raise RuntimeError("Se encontro un archivo de senal inesperado: " + os.path.join(folder, name) +\\\\n                                   ". No se ha borrado nada; revise la copia y detenga este flujo.")\\\\n\\\\n\\\\ndef preflight(api, plan):\\\\n    if plan.get("example_only") or not plan.get("can_prepare"):\\\\n        raise RuntimeError("Este plan esta marcado como EJEMPLO. Edite config.json, confirme la correspondencia de la secuencia y regenere con example_only=false.")\\\\n    cfg = plan["config"]\\\\n    current = api.CURDATA()\\\\n    if not current or len(current) != 4:\\\\n        raise RuntimeError("Abra un dataset con CURDATA de cuatro campos [nombre, expno, procno, directorio]. No se admite el layout antiguo con usuario adicional.")\\\\n    current = list(current)\\\\n    if cfg["expected_dataset_name"] and text_type(current[0]) != cfg["expected_dataset_name"]:\\\\n        raise RuntimeError("Dataset inesperado. Se esperaba " + cfg["expected_dataset_name"] + "; actual: " + text_type(current[0]))\\\\n    dataset_name = text_type(current[0])\\\\n    if dataset_name in (".", "..") or any(c in dataset_name for c in ("/", "\\\\\\\\\\\\\\\\", "\\\\\\\\0")):\\\\n        raise RuntimeError("Nombre de dataset no valido para el layout directo.")\\\\n    root = os.path.realpath(text_type(current[3]))\\\\n    dataset_dir = os.path.join(root, dataset_name)\\\\n    if not os.path.isdir(dataset_dir):\\\\n        raise RuntimeError("No existe la ruta directa del dataset: " + dataset_dir)\\\\n    template = [dataset_name, text_type(cfg["template_expno"]), text_type(cfg["template_procno"]), root]\\\\n    template_dir = os.path.join(dataset_dir, template[1])\\\\n    template_proc_dir = os.path.join(template_dir, "pdata", template[2])\\\\n    if not (os.path.isfile(os.path.join(template_dir, "acqu")) or os.path.isfile(os.path.join(template_dir, "acqus"))):\\\\n        raise RuntimeError("La plantilla no tiene parametros de adquisicion: " + template_dir)\\\\n    if not (os.path.isfile(os.path.join(template_proc_dir, "proc")) or os.path.isfile(os.path.join(template_proc_dir, "procs"))):\\\\n        raise RuntimeError("La plantilla no tiene parametros de procesado en PROCNO esperado: " + template_proc_dir)\\\\n    destinations = []\\\\n    seen = set()\\\\n    for row in plan["rows"]:\\\\n        expno = text_type(row["expno"])\\\\n        if not expno.isdigit() or int(expno) <= 0 or expno in seen or expno == template[1]:\\\\n            raise RuntimeError("EXPNO invalido, duplicado o igual a plantilla: " + expno)\\\\n        seen.add(expno)\\\\n        path = os.path.join(dataset_dir, expno)\\\\n        destinations.append(path)\\\\n    # TODAS las colisiones se comprueban antes de RE / wraparam / PUTPAR.\\\\n    collisions = [p for p in destinations if os.path.lexists(p)]\\\\n    if collisions:\\\\n        raise RuntimeError("Los destinos ya existen. No se escribe ningun experimento:\\\\\\\\n" + "\\\\\\\\n".join(collisions))\\\\n    if cfg["delay_values_s"] is not None and not cfg["delay_mapping_confirmed"]:\\\\n        raise RuntimeError("Falta verificar la correspondencia del parametro D en esta secuencia.")\\\\n    if cfg["pulse_value_us"] is not None and not cfg["pulse_mapping_confirmed"]:\\\\n        raise RuntimeError("Falta verificar la correspondencia del parametro P en esta secuencia.")\\\\n    return current, template, destinations\\\\n\\\\n\\\\ndef set_and_verify(api, key, value):\\\\n    api.PUTPAR(key, format_value(value))\\\\n    observed = finite_number(api.GETPAR(key))\\\\n    if abs(observed - float(value)) > max(1e-9, abs(float(value)) * 1e-7):\\\\n        raise RuntimeError("No se ha confirmado " + key + ": esperado " + format_value(value) + ", leido " + text_type(observed))\\\\n\\\\n\\\\ndef prepare(api, plan):\\\\n    original, template, paths = preflight(api, plan)\\\\n    created = []\\\\n    problem = None\\\\n    try:\\\\n        api.RE(template)\\\\n        if not equivalent_dataset(api.CURDATA(), template):\\\\n            raise RuntimeError("RE no ha abierto la plantilla prevista.")\\\\n        if finite_number(api.GETPAR("PARMODE")) != 0:\\\\n            raise RuntimeError("La plantilla debe ser 1D (PARMODE=0) para estas rampas de EXPNO independientes.")\\\\n        actual_program = text_type(api.GETPAR("PULPROG")).strip().strip("<>")\\\\n        expected = plan["config"]["expected_pulse_program"]\\\\n        if expected and actual_program != expected:\\\\n            raise RuntimeError("PULPROG de plantilla no coincide: " + actual_program + "; esperado: " + expected)\\\\n        for row, path in zip(plan["rows"], paths):\\\\n            # Repetir la comprobacion protege frente a un destino creado desde otro proceso.\\\\n            if os.path.lexists(path):\\\\n                raise RuntimeError("El destino aparecio durante la preparacion: " + path)\\\\n            api.RE(template)\\\\n            if not equivalent_dataset(api.CURDATA(), template):\\\\n                raise RuntimeError("Se perdio la plantilla antes de copiar parametros.")\\\\n            # wraparam: copia solo parametros; NO usar wrpa/WR (copian datos).\\\\n            api.XCMD("wraparam " + text_type(row["expno"]), wait=api.WAIT_TILL_DONE)\\\\n            if not os.path.isdir(path):\\\\n                raise RuntimeError("wraparam no creo el destino: " + path)\\\\n            created.append(path)\\\\n            ensure_parameter_only(path)\\\\n            destination = [template[0], text_type(row["expno"]), text_type(row["procno"]), template[3]]\\\\n            api.RE(destination)\\\\n            if not equivalent_dataset(api.CURDATA(), destination):\\\\n                raise RuntimeError("RE no abrio el destino previsto: " + path)\\\\n            set_and_verify(api, "GPZ " + text_type(row["gradient_index"]), row["gradient_percent"])\\\\n            if row["delay_s"] is not None:\\\\n                set_and_verify(api, parameter_key(row["delay_parameter"]), row["delay_s"])\\\\n            if row["pulse_us"] is not None:\\\\n                set_and_verify(api, parameter_key(row["pulse_parameter"]), row["pulse_us"])\\\\n            if row["dummy_scans"] is not None:\\\\n                set_and_verify(api, "DS", row["dummy_scans"])\\\\n    except Exception as error:\\\\n        problem = text_type(error)\\\\n    finally:\\\\n        try:\\\\n            api.RE(original)\\\\n            if not equivalent_dataset(api.CURDATA(), original):\\\\n                raise RuntimeError("RE no restauro el dataset original.")\\\\n        except Exception as restore_error:\\\\n            restore_message = "No se ha podido restaurar el dataset original: " + text_type(restore_error)\\\\n            problem = restore_message if problem is None else problem + "\\\\\\\\n" + restore_message\\\\n    if problem is not None:\\\\n        # Un comando puede crear el directorio y fallar antes de devolver el control.\\\\n        present = [p for p in paths if os.path.lexists(p)]\\\\n        raise RuntimeError(problem + "\\\\\\\\nPreparacion detenida. Directorios nuevos ya creados: " + text_type(len(present)) +\\\\n                           ". No se ha adquirido ni borrado ningun dato.\\\\\\\\n" + "\\\\\\\\n".join(present))\\\\n    return created\\\\n\\\\n\\\')\\n_load_module(\\\'_dosy_calibration\\\', \\\'# -*- coding: utf-8 -*-\\\\n"""Read-only DOSY reference calibration, compatible with Jython 2.7 / Python 3.\\\\n\\\\nNo TopSpin imports or third-party dependencies. No files are modified here.\\\\nThe fitted empirical b coefficient applies only to the recorded pulse sequence,\\\\ngradient shape, probe and timings. It is NOT a universal gradient constant.\\\\n"""\\\\nfrom __future__ import division\\\\n\\\\nimport hashlib\\\\nimport math\\\\nimport os\\\\nimport re\\\\nimport struct\\\\n\\\\nVERSION = "1.0.0"\\\\n\\\\n\\\\nclass CalibrationError(ValueError):\\\\n    """Input cannot safely support this calibration workflow."""\\\\n\\\\n\\\\ndef _finite(value, label, positive=False):\\\\n    try:\\\\n        value = float(value)\\\\n    except (TypeError, ValueError, OverflowError):\\\\n        raise CalibrationError("%s must be a finite number" % label)\\\\n    if math.isnan(value) or math.isinf(value) or (positive and value <= 0):\\\\n        raise CalibrationError("%s must be %sfinite" %\\\\n                               (label, "positive and " if positive else ""))\\\\n    return value\\\\n\\\\n\\\\ndef _integer(value, label, minimum=None):\\\\n    number = _finite(value, label)\\\\n    if number != int(number) or (minimum is not None and number < minimum):\\\\n        raise CalibrationError("%s must be an integer >= %s" % (label, minimum))\\\\n    return int(number)\\\\n\\\\n\\\\ndef _read_bytes(path):\\\\n    try:\\\\n        with open(path, "rb") as handle:\\\\n            return handle.read()\\\\n    except (IOError, OSError) as exc:\\\\n        raise CalibrationError("Cannot read %s: %s" % (path, exc))\\\\n\\\\n\\\\ndef _source(path, content):\\\\n    return {"path": os.path.abspath(path), "sha256": hashlib.sha256(content).hexdigest(),\\\\n            "bytes": len(content)}\\\\n\\\\n\\\\ndef _token(value):\\\\n    value = value.strip()\\\\n    if value.startswith("<") and value.endswith(">"):\\\\n        return value[1:-1]\\\\n    if re.match(r"^[+-]?\\\\\\\\d+$", value):\\\\n        return int(value)\\\\n    try:\\\\n        return float(value.replace("D", "E").replace("d", "e"))\\\\n    except ValueError:\\\\n        return value\\\\n\\\\n\\\\ndef parse_jcamp(text):\\\\n    """Parse status parameters, including multiline <strings> and indexed arrays.\\\\n\\\\n    Unknown scalar strings are retained. Unsupported array compression or a\\\\n    mismatched declared length is rejected, never silently reindexed.\\\\n    """\\\\n    records = {}\\\\n    key = None\\\\n    body = []\\\\n    # Strip comments only outside angle-bracket strings; \\\\\\\'$$\\\\\\\' can occur in paths.\\\\n    in_string = False\\\\n    for raw in text.splitlines():\\\\n        clean = []\\\\n        pos = 0\\\\n        while pos < len(raw):\\\\n            char = raw[pos]\\\\n            if not in_string and raw[pos:pos + 2] == "$$":\\\\n                break\\\\n            clean.append(char)\\\\n            if char == "<":\\\\n                in_string = True\\\\n            elif char == ">":\\\\n                in_string = False\\\\n            pos += 1\\\\n        line = "".join(clean)\\\\n        match = re.match(r"^##\\\\\\\\$([^=]+)=\\\\\\\\s*(.*)$", line)\\\\n        if match or line.startswith("##"):\\\\n            if key is not None:\\\\n                records[key] = "\\\\\\\\n".join(body).strip()\\\\n            key = match.group(1).strip() if match else None\\\\n            body = [match.group(2)] if match else []\\\\n        elif key is not None:\\\\n            body.append(line)\\\\n    if key is not None:\\\\n        records[key] = "\\\\\\\\n".join(body).strip()\\\\n    if in_string:\\\\n        raise CalibrationError("Unterminated JCAMP angle-bracket string")\\\\n    result = {}\\\\n    for key, value in records.items():\\\\n        array = re.match(r"^\\\\\\\\(\\\\\\\\s*(\\\\\\\\d+)\\\\\\\\s*\\\\\\\\.\\\\\\\\.\\\\\\\\s*(\\\\\\\\d+)\\\\\\\\s*\\\\\\\\)\\\\\\\\s*(.*)$", value, re.S)\\\\n        if array:\\\\n            start, end = int(array.group(1)), int(array.group(2))\\\\n            if end < start or end > 1000000:\\\\n                raise CalibrationError("Invalid JCAMP array bounds: %s" % key)\\\\n            tokens = re.findall(r"<[^>]*>|[^\\\\\\\\s]+", array.group(3), re.S)\\\\n            if len(tokens) != end - start + 1:\\\\n                raise CalibrationError("JCAMP array %s has %s values, expected %s" %\\\\n                                       (key, len(tokens), end - start + 1))\\\\n            result[key] = [None] * start + [_token(item) for item in tokens]\\\\n        elif value.startswith("("):\\\\n            raise CalibrationError("Unsupported JCAMP array declaration: %s" % key)\\\\n        else:\\\\n            result[key] = _token(value)\\\\n    return result\\\\n\\\\n\\\\ndef read_jcamp(path):\\\\n    content = _read_bytes(path)\\\\n    try:\\\\n        text = content.decode("utf-8-sig")\\\\n    except UnicodeDecodeError:\\\\n        text = content.decode("cp1252")\\\\n    return parse_jcamp(text), _source(path, content)\\\\n\\\\n\\\\ndef _required(parameters, key, index=None):\\\\n    name = key if index is None else "%s%s" % (key, index)\\\\n    if index is not None and name in parameters:\\\\n        value = parameters[name]\\\\n    elif key not in parameters:\\\\n        raise CalibrationError("Missing required status parameter %s" % name)\\\\n    elif index is None:\\\\n        value = parameters[key]\\\\n    else:\\\\n        array = parameters[key]\\\\n        if not isinstance(array, list) or len(array) <= index:\\\\n            raise CalibrationError("Missing required indexed parameter %s" % name)\\\\n        value = array[index]\\\\n    if value is None or value == "":\\\\n        raise CalibrationError("Empty required status parameter %s" % name)\\\\n    return value\\\\n\\\\n\\\\ndef read_processed_1r(experiment_dir, procno=1):\\\\n    """Read one acquired, processed real 1D spectrum and its provenance.\\\\n\\\\n    1i is a normal separate imaginary component and may coexist with 1r.\\\\n    Multidimensional spectra, extracted regions and ambiguous layouts reject.\\\\n    DTYPP=0: int32 * 2**NC_proc. DTYPP=2: float64 directly (NC_proc ignored).\\\\n    """\\\\n    procno = _integer(procno, "PROCNO", 1)\\\\n    experiment_dir = os.path.abspath(experiment_dir)\\\\n    pdata = os.path.join(experiment_dir, "pdata", str(procno))\\\\n    acqus, asource = read_jcamp(os.path.join(experiment_dir, "acqus"))\\\\n    procs, psource = read_jcamp(os.path.join(pdata, "procs"))\\\\n    if _integer(_required(acqus, "PARMODE"), "PARMODE") != 0:\\\\n        raise CalibrationError("Only acquired 1D experiments (PARMODE=0) are supported")\\\\n    for name in ("proc2s", "proc3s", "2rr", "3rrr", "2ri", "2ir", "2ii"):\\\\n        if os.path.exists(os.path.join(pdata, name)):\\\\n            raise CalibrationError("Multidimensional/extracted layout is unsupported: %s" % name)\\\\n    si = _integer(_required(procs, "SI"), "SI", 2)\\\\n    if si > 16777216:\\\\n        raise CalibrationError("SI exceeds the supported in-memory 1D size")\\\\n    for name in ("STSI", "FTSIZE"):\\\\n        if name in procs and _integer(procs[name], name) not in (0, si):\\\\n            raise CalibrationError("Extracted/cropped processing layout: %s differs from SI" % name)\\\\n    if "STSR" in procs and _integer(procs["STSR"], "STSR") != 0:\\\\n        raise CalibrationError("Extracted/cropped processing layout: STSR is not zero")\\\\n    if not _same(procs.get("AXLEFT", 0), procs.get("AXRIGHT", 0)):\\\\n        raise CalibrationError("Custom AXLEFT/AXRIGHT axis is unsupported; use the frequency ppm axis")\\\\n    if "FT_mod" in procs and _integer(procs["FT_mod"], "FT_mod") == 0:\\\\n        raise CalibrationError("The spectrum has no Fourier-transform status")\\\\n    sf = _finite(_required(procs, "SF"), "SF (MHz)", True)\\\\n    sw = _finite(_required(procs, "SW_p"), "SW_p (Hz)", True)\\\\n    offset = _finite(_required(procs, "OFFSET"), "OFFSET (ppm)")\\\\n    nc = _integer(_required(procs, "NC_proc"), "NC_proc")\\\\n    dtype = _integer(_required(procs, "DTYPP"), "DTYPP")\\\\n    order = _integer(_required(procs, "BYTORDP"), "BYTORDP")\\\\n    if dtype not in (0, 2) or order not in (0, 1):\\\\n        raise CalibrationError("Supported layouts: DTYPP=0/2 and BYTORDP=0/1 only")\\\\n    try:\\\\n        scale = math.ldexp(1.0, nc) if dtype == 0 else 1.0\\\\n    except (OverflowError, ValueError):\\\\n        raise CalibrationError("Invalid NC_proc scale")\\\\n    if scale == 0 or math.isinf(scale):\\\\n        raise CalibrationError("NC_proc scale is outside floating-point range")\\\\n    itemsize, code = (4, "i") if dtype == 0 else (8, "d")\\\\n    path = os.path.join(pdata, "1r")\\\\n    content = _read_bytes(path)\\\\n    expected = si * itemsize\\\\n    if len(content) != expected:\\\\n        padded = ((expected + 1023) // 1024) * 1024\\\\n        tail = content[expected:]\\\\n        if len(content) != padded or len(content) < expected or tail.strip(b"\\\\\\\\x00"):\\\\n            raise CalibrationError("1r size/layout mismatch: %s bytes, expected %s" %\\\\n                                   (len(content), expected))\\\\n    endian = "<" if order == 0 else ">"\\\\n    # Chunk unpacking avoids a huge struct format and works on Jython 2.7.\\\\n    values = []\\\\n    for start in range(0, si, 4096):\\\\n        count = min(4096, si - start)\\\\n        chunk = struct.unpack(endian + str(count) + code,\\\\n                              content[start * itemsize:(start + count) * itemsize])\\\\n        for value in chunk:\\\\n            values.append(_finite(value * scale, "scaled 1r point"))\\\\n    step = sw / sf / si\\\\n    sources = [asource, psource, _source(path, content)]\\\\n    saved_files = {}\\\\n    for name in ("pulseprogram", "gpnam6"):\\\\n        saved = os.path.join(experiment_dir, name)\\\\n        if os.path.isfile(saved):\\\\n            entry = _source(saved, _read_bytes(saved))\\\\n            saved_files[name] = entry["sha256"]\\\\n            sources.append(entry)\\\\n    return {"values": values, "ppm_start": offset, "ppm_step": step,\\\\n            "ppm_end": offset - (si - 1) * step,\\\\n            "acquisition": acqus, "processing": procs, "sources": sources,\\\\n            "saved_file_hashes": saved_files}\\\\n\\\\n\\\\ndef integrate_region(spectrum, ppm_low, ppm_high):\\\\n    """Signed trapezoidal area in intensity*ppm with exact interpolated bounds."""\\\\n    low = _finite(ppm_low, "ppm_low")\\\\n    high = _finite(ppm_high, "ppm_high")\\\\n    if low >= high:\\\\n        raise CalibrationError("ppm_low must be less than ppm_high")\\\\n    start, step, end = spectrum["ppm_start"], spectrum["ppm_step"], spectrum["ppm_end"]\\\\n    values = spectrum["values"]\\\\n    tolerance = 1e-10 * max(1.0, abs(start), abs(end))\\\\n    if low < end - tolerance or high > start + tolerance:\\\\n        raise CalibrationError("The full %.9g..%.9g ppm window is outside %.9g..%.9g ppm" %\\\\n                               (low, high, end, start))\\\\n    a = min(len(values) - 1.0, max(0.0, (start - high) / step))\\\\n    b = min(len(values) - 1.0, max(0.0, (start - low) / step))\\\\n    if b - a < 2:\\\\n        raise CalibrationError("Integration window must span at least two spectral intervals")\\\\n    def at(index):\\\\n        left = int(math.floor(index))\\\\n        right = min(left + 1, len(values) - 1)\\\\n        return values[left] + (index - left) * (values[right] - values[left])\\\\n    previous_x, previous_y = a, at(a)\\\\n    areas = []\\\\n    for index in range(int(math.floor(a)) + 1, int(math.ceil(b))):\\\\n        value = values[index]\\\\n        areas.append((index - previous_x) * (previous_y + value) * 0.5)\\\\n        previous_x, previous_y = float(index), value\\\\n    areas.append((b - previous_x) * (previous_y + at(b)) * 0.5)\\\\n    area = _finite(math.fsum(areas) * step, "signed integral", True)\\\\n    return {"integral": area, "unit": "scaled_intensity*ppm", "ppm_low": low,\\\\n            "ppm_high": high, "intervals": b - a,\\\\n            "method": "signed trapezoid with linear boundary interpolation; no abs, baseline or normalization"}\\\\n\\\\n\\\\ndef fit_attenuation(gradient_percent, intensities):\\\\n    """Unweighted free-intercept OLS of log(I/Imax) vs (GPZ6/100)^2."""\\\\n    if len(gradient_percent) != len(intensities) or len(intensities) < 4:\\\\n        raise CalibrationError("At least four paired attenuation points are required")\\\\n    gradients = [_finite(v, "gradient percentage") for v in gradient_percent]\\\\n    if any(abs(v) > 100 for v in gradients):\\\\n        raise CalibrationError("Absolute gradient percentages must not exceed 100")\\\\n    values = [_finite(v, "integral", True) for v in intensities]\\\\n    x = [(v / 100.0) ** 2 for v in gradients]\\\\n    if len(set(round(v, 12) for v in x)) < 4:\\\\n        raise CalibrationError("At least four distinct squared gradient amplitudes are required")\\\\n    maximum = max(values)\\\\n    y = [math.log(v) - math.log(maximum) for v in values]\\\\n    n = len(x)\\\\n    xmean, ymean = math.fsum(x) / n, math.fsum(y) / n\\\\n    sxx = math.fsum((v - xmean) ** 2 for v in x)\\\\n    if sxx <= 1e-24:\\\\n        raise CalibrationError("Gradient span is too small for stable calibration")\\\\n    syy = math.fsum((v - ymean) ** 2 for v in y)\\\\n    slope = math.fsum((a - xmean) * (b - ymean) for a, b in zip(x, y)) / sxx\\\\n    if slope >= 0 or syy <= 1e-24:\\\\n        raise CalibrationError("Calibration requires a nonzero, decreasing attenuation")\\\\n    intercept = ymean - slope * xmean\\\\n    fitted_log = [intercept + slope * v for v in x]\\\\n    residuals = [a - b for a, b in zip(y, fitted_log)]\\\\n    sse = math.fsum(v * v for v in residuals)\\\\n    stderr = math.sqrt(max(0.0, sse / (n - 2) / sxx))\\\\n    try:\\\\n        predicted = [math.exp(math.log(maximum) + v) for v in fitted_log]\\\\n        zero = math.exp(math.log(maximum) + intercept)\\\\n    except OverflowError:\\\\n        raise CalibrationError("Extrapolated I(0) or predicted intensity overflows")\\\\n    return {"model": "ln(I/Imax) = intercept + slope * (GPZ6/100)^2",\\\\n            "weighting": "unweighted ordinary least squares in log intensity",\\\\n            "n": n, "distinct_x": len(set(x)), "x": x, "log_relative_intensity": y,\\\\n            "slope": slope, "slope_abs": -slope, "slope_SE": stderr,\\\\n            "intercept_log_I_over_Imax": intercept, "Imax": maximum,\\\\n            "I0_extrapolated": zero, "R2": 1.0 - sse / syy,\\\\n            "degrees_of_freedom": n - 2, "residuals_log": residuals,\\\\n            "predicted_integrals": predicted, "observed_integrals": values,\\\\n            "relative_slope_uncertainty_1sigma": stderr / abs(slope),\\\\n            "relative_attenuation_last_over_first": values[-1] / values[0],\\\\n            "uncertainty_scope": "Regression standard error only; excludes Dref, temperature, processing and systematic uncertainty"}\\\\n\\\\n\\\\ndef _metadata(spectrum):\\\\n    a = spectrum["acquisition"]\\\\n    result = {}\\\\n    for key in ("PULPROG", "PROBHD", "NUC1"):\\\\n        value = _required(a, key)\\\\n        if not isinstance(value, type(u"")) and not isinstance(value, str):\\\\n            raise CalibrationError("%s must be a string" % key)\\\\n        result[key] = value.strip()\\\\n    result["GPNAM6"] = _required(a, "GPNAM", 6)\\\\n    for key, array, index in (("D20", "D", 20), ("D16", "D", 16),\\\\n                              ("P30", "P", 30), ("GPZ6", "GPZ", 6)):\\\\n        result[key] = _finite(_required(a, array, index), key)\\\\n    for key in ("RG", "NS", "TE"):\\\\n        result[key] = _finite(_required(a, key), key, True)\\\\n    if result["D20"] <= 0 or result["P30"] <= 0 or result["D16"] < 0:\\\\n        raise CalibrationError("D20/P30 must be positive and D16 nonnegative")\\\\n    result["NS"] = _integer(result["NS"], "NS", 1)\\\\n    # These parameters can affect amplitudes; if supplied require them constant.\\\\n    for key in ("DS", "AQ_mod", "TD", "SW_h", "SFO1"):\\\\n        if key in a:\\\\n            result[key] = a[key]\\\\n    for key, index in (("D1", 1),):\\\\n        if "D" in a and isinstance(a["D"], list) and len(a["D"]) > index:\\\\n            result[key] = a["D"][index]\\\\n    # Preserve and compare every saved pulse delay, pulse duration and gradient\\\\n    # component/shape. Only the GPZ6 amplitude is allowed to vary in this ramp.\\\\n    pulse_gradient = {}\\\\n    array_names = ("D", "P", "GPX", "GPY", "GPZ", "GPNAM")\\\\n    for key in a:\\\\n        if key in array_names:\\\\n            if not isinstance(a[key], list):\\\\n                raise CalibrationError("Expected indexed parameter array %s" % key)\\\\n            items = list(a[key])\\\\n            if key == "GPZ" and len(items) > 6:\\\\n                items[6] = None\\\\n            pulse_gradient[key] = items\\\\n        elif re.match(r"^(D|P|GPX|GPY|GPZ|GPNAM)\\\\\\\\d+$", key) and key != "GPZ6":\\\\n            pulse_gradient[key] = a[key]\\\\n    result["pulse_gradient_parameters"] = pulse_gradient\\\\n    return result\\\\n\\\\n\\\\ndef _same(a, b):\\\\n    if isinstance(a, (int, float)) and isinstance(b, (int, float)):\\\\n        return abs(a - b) <= 1e-10 * max(1.0, abs(a), abs(b))\\\\n    return a == b\\\\n\\\\n\\\\ndef analyze_series(dataset_dir, expnos, procno, ppm_low, ppm_high, dref_1e9,\\\\n                   reference_temperature_K, reference_label,\\\\n                   max_temperature_span_K=0.5,\\\\n                   max_reference_temperature_difference_K=0.5):\\\\n    """Integrate and calibrate a single constant-timing gradient ramp.\\\\n\\\\n    Dref in 10^-9 m^2/s must refer to the explicitly entered reference temperature.\\\\n    TE is recorded spectrometer metadata, not an independent sample thermometer.\\\\n    Thresholds may be changed explicitly; temperature is never corrected silently.\\\\n    """\\\\n    dref = _finite(dref_1e9, "Dref (10^-9 m^2/s)", True)\\\\n    tref = _finite(reference_temperature_K, "reference temperature (K)", True)\\\\n    tspan = _finite(max_temperature_span_K, "maximum temperature span")\\\\n    tdiff = _finite(max_reference_temperature_difference_K, "maximum reference temperature difference")\\\\n    if tspan < 0 or tdiff < 0:\\\\n        raise CalibrationError("Temperature tolerances must be nonnegative")\\\\n    if not reference_label or not reference_label.strip():\\\\n        raise CalibrationError("A reference identity/source label is required")\\\\n    numbers = [_integer(v, "EXPNO", 1) for v in expnos]\\\\n    if len(numbers) < 4 or len(set(numbers)) != len(numbers):\\\\n        raise CalibrationError("Provide at least four different experiment numbers")\\\\n    rows, sources, warnings = [], [], []\\\\n    baseline, processing_baseline, saved_baseline = None, None, None\\\\n    processing_keys = ("SI", "FTSIZE", "SF", "SW_p", "OFFSET", "FT_mod", "WDW",\\\\n                       "LB", "GB", "SSB", "BC_mod", "PH_mod")\\\\n    processing_record = ("PHC0", "PHC1", "ABSF1", "ABSF2", "ABSG", "ABSL", "INTBC",\\\\n                         "NC_proc", "DTYPP", "BYTORDP") + processing_keys\\\\n    varying_processing = set()\\\\n    first_processing = None\\\\n    for expno in numbers:\\\\n        try:\\\\n            spectrum = read_processed_1r(os.path.join(dataset_dir, str(expno)), procno)\\\\n            meta = _metadata(spectrum)\\\\n            area = integrate_region(spectrum, ppm_low, ppm_high)\\\\n        except CalibrationError as exc:\\\\n            raise CalibrationError("EXPNO %s: %s" % (expno, exc))\\\\n        processing = dict((k, spectrum["processing"].get(k)) for k in processing_record)\\\\n        stable = dict((k, v) for k, v in meta.items() if k not in ("GPZ6", "TE", "DS"))\\\\n        stable_processing = dict((k, processing[k]) for k in processing_keys)\\\\n        saved = spectrum["saved_file_hashes"]\\\\n        if baseline is None:\\\\n            baseline, processing_baseline, saved_baseline = stable, stable_processing, saved\\\\n            first_processing = processing\\\\n        else:\\\\n            for key in set(baseline) | set(stable):\\\\n                if not _same(baseline.get(key), stable.get(key)):\\\\n                    raise CalibrationError("EXPNO %s: inconsistent %s across the calibration ramp" % (expno, key))\\\\n            for key in processing_keys:\\\\n                if not _same(processing_baseline[key], stable_processing[key]):\\\\n                    raise CalibrationError("EXPNO %s: inconsistent processing %s; reprocess consistently" % (expno, key))\\\\n            if saved != saved_baseline:\\\\n                raise CalibrationError("EXPNO %s: saved pulseprogram/gpnam6 provenance differs or is missing" % expno)\\\\n            for key in ("PHC0", "PHC1", "ABSF1", "ABSF2", "ABSG", "ABSL", "INTBC"):\\\\n                if not _same(first_processing[key], processing[key]):\\\\n                    varying_processing.add(key)\\\\n        rows.append({"expno": expno, "procno": int(procno), "gradient_percent": meta["GPZ6"],\\\\n                     "x_gradient_fraction_squared": (meta["GPZ6"] / 100.0) ** 2,\\\\n                     "integral": area["integral"], "integration": area,\\\\n                     "acquisition": meta, "processing": processing,\\\\n                     "saved_file_hashes": saved})\\\\n        sources.extend(spectrum["sources"])\\\\n    temperatures = [row["acquisition"]["TE"] for row in rows]\\\\n    tmin, tmax = min(temperatures), max(temperatures)\\\\n    tmean = math.fsum(temperatures) / len(temperatures)\\\\n    if tmax - tmin > tspan + 1e-9:\\\\n        raise CalibrationError("TE drift %.6g K exceeds %.6g K; stabilize temperature or explicitly reassess tolerance/reference" %\\\\n                               (tmax - tmin, tspan))\\\\n    if max(abs(t - tref) for t in temperatures) > tdiff + 1e-9:\\\\n        raise CalibrationError("Reference temperature %.6g K differs from recorded TE by more than %.6g K; supply the appropriate Dref(T)" %\\\\n                               (tref, tdiff))\\\\n    fit = fit_attenuation([r["gradient_percent"] for r in rows], [r["integral"] for r in rows])\\\\n    for i, row in enumerate(rows):\\\\n        row["log_relative_intensity"] = fit["log_relative_intensity"][i]\\\\n        row["predicted_integral"] = fit["predicted_integrals"][i]\\\\n        row["residual_log"] = fit["residuals_log"][i]\\\\n    coefficient = fit["slope_abs"] / (dref * 1e-9)\\\\n    b_se = fit["slope_SE"] / (dref * 1e-9)\\\\n    if varying_processing:\\\\n        warnings.append("Phase/baseline status varies: %s. Inspect every spectrum before accepting." % ", ".join(sorted(varying_processing)))\\\\n    if len(saved_baseline) != 2:\\\\n        warnings.append("Saved pulseprogram and/or gpnam6 are absent. Scope uses parameter names; physical gradient conversion is unavailable.")\\\\n    if len(set(row["acquisition"].get("DS") for row in rows)) > 1:\\\\n        warnings.append("DS differs across the ramp. Verify steady-state preparation; amplitudes were not normalized by dummy scans.")\\\\n    if fit["R2"] < 0.98:\\\\n        warnings.append("R2 < 0.98: inspect residuals, overlap, baseline, convection and signal-to-noise; no automatic acceptance.")\\\\n    if fit["relative_slope_uncertainty_1sigma"] > 0.05:\\\\n        warnings.append("Regression slope relative standard error exceeds 5%; review the ramp and reference signal.")\\\\n    if tmax - tmin > 0.1:\\\\n        warnings.append("Recorded TE varies by %.4g K. A single supplied Dref is used; no thermal correction was inferred." % (tmax - tmin))\\\\n    warnings.append("Positive signed area and a good fit do not establish peak purity or signal-to-noise. Inspect spectra and residuals.")\\\\n    profile = {"kind": "empirical_b_per_gradient_fraction_squared",\\\\n               "b_at_100_percent_s_m2": coefficient, "b_coefficient_SE_s_m2": b_se,\\\\n               "definition": "b(g) = b_at_100_percent_s_m2 * (GPZ6/100)^2",\\\\n               "Dref_1e9_m2_s": dref, "reference_temperature_K": tref,\\\\n               "reference_label": reference_label.strip(),\\\\n               "Dref_uncertainty": "not supplied; excluded from reported standard error",\\\\n               "scope": dict(baseline), "saved_file_hashes": saved_baseline,\\\\n               "transfer_policy": "Same pulse sequence, timings, gradient shape and probe only; not transferable across big Delta or small delta without a verified pulse-sequence model",\\\\n               "bruker_gradient_constant": None,\\\\n               "status": "candidate requiring spectral and residual review; not written to gradpar"}\\\\n    return {"schema_version": 1, "software": "DiffAtOnce TopSpin DOSY calibration " + VERSION,\\\\n            "dataset_dir": os.path.abspath(dataset_dir), "procno": int(procno),\\\\n            "expnos": numbers, "ppm_region": {"low": float(ppm_low), "high": float(ppm_high)},\\\\n            "rows": rows, "fit": fit, "calibration_profile": profile,\\\\n            "temperature": {"source": "acqus TE status; not independent sample thermometry",\\\\n                            "minimum_K": tmin, "maximum_K": tmax, "mean_K": tmean,\\\\n                            "span_K": tmax - tmin, "reference_K": tref,\\\\n                            "max_span_allowed_K": tspan, "max_reference_difference_allowed_K": tdiff,\\\\n                            "correction_applied": False},\\\\n            "warnings": warnings, "sources": sources,\\\\n            "provenance_policy": "All inputs read-only; SHA-256 refers to bytes used for this calculation"}\\\\n\\\\n\\\\ndef gradient_correction(old_gradient_constant, measured_diffusion, reference_diffusion,\\\\n                        gradient_unit="G/cm", diffusion_unit="10^-9 m^2/s"):\\\\n    """Separate ratio correction; Dmeasured and Dref must use the same units.\\\\n\\\\n    Dmeasured must have been fitted using old_gradient_constant. This function\\\\n    does not derive Dmeasured from the empirical slope or alter TopSpin settings.\\\\n    """\\\\n    old = _finite(old_gradient_constant, "old gradient constant", True)\\\\n    measured = _finite(measured_diffusion, "measured diffusion", True)\\\\n    reference = _finite(reference_diffusion, "reference diffusion", True)\\\\n    factor = math.sqrt(measured / reference)\\\\n    new = _finite(old * factor, "new gradient constant", True)\\\\n    return {"old_gradient_constant": old, "new_gradient_constant": new,\\\\n            "gradient_unit": gradient_unit, "measured_diffusion": measured,\\\\n            "reference_diffusion": reference, "diffusion_unit": diffusion_unit,\\\\n            "factor": factor, "formula": "G_new = G_old * sqrt(D_measured / D_reference)",\\\\n            "assumption": "D_measured was evaluated using G_old, matching reference temperature and the correct pulse-sequence b model",\\\\n            "written_to_spectrometer": False}\\\\n\\\')\\n_load_module(\\\'_dosy_console_ui\\\', \\\'# -*- coding: utf-8 -*-\\\\n"""Native TopSpin dialogs. Jython 2.7 / CPython 3 standard library only."""\\\\nfrom __future__ import print_function, unicode_literals\\\\nimport datetime\\\\nimport io\\\\nimport json\\\\nimport math\\\\nimport os\\\\nimport re\\\\nimport uuid\\\\nimport _dosy_ramp_engine as ramp\\\\nimport _dosy_calibration as calibration\\\\n\\\\nTBO_PROFILE = {}\\\\nTBO_MODEL_SOURCE_SHA256 = \\\\\\\'\\\\\\\'\\\\ntry:\\\\n    text_type = unicode\\\\nexcept NameError:\\\\n    text_type = str\\\\n\\\\ndef ask(api, title, labels, defaults, header=\\\\\\\'\\\\\\\'):\\\\n    result = api.INPUT_DIALOG(title, header, labels, [text_type(v) for v in defaults],\\\\n                              [\\\\\\\'\\\\\\\'] * len(labels), [\\\\\\\'1\\\\\\\'] * len(labels))\\\\n    if result is None:\\\\n        return None\\\\n    return [text_type(v).strip() for v in result]\\\\n\\\\ndef current_dataset(api):\\\\n    data = api.CURDATA()\\\\n    if not data or len(data) != 4:\\\\n        raise ValueError(\\\\\\\'Abra un dataset [nombre, EXPNO, PROCNO, directorio].\\\\\\\')\\\\n    name = text_type(data[0])\\\\n    if name in (\\\\\\\'.\\\\\\\', \\\\\\\'..\\\\\\\') or any(c in name for c in (\\\\\\\'/\\\\\\\', \\\\\\\'\\\\\\\\\\\\\\\\\\\\\\\', \\\\\\\'\\\\\\\\x00\\\\\\\')):\\\\n        raise ValueError(\\\\\\\'Nombre de dataset no admitido.\\\\\\\')\\\\n    folder = os.path.realpath(os.path.join(text_type(data[3]), name))\\\\n    if not os.path.isdir(folder):\\\\n        raise ValueError(\\\\\\\'Dataset no encontrado: \\\\\\\' + folder)\\\\n    return list(data), folder\\\\n\\\\ndef positive(value, label):\\\\n    number = float(value)\\\\n    if math.isnan(number) or math.isinf(number) or number <= 0:\\\\n        raise ValueError(label + \\\\\\\': debe ser positivo y finito.\\\\\\\')\\\\n    return number\\\\n\\\\ndef parse_expnos(text):\\\\n    result = []\\\\n    for term in text.split(\\\\\\\',\\\\\\\'):\\\\n        term = term.strip()\\\\n        if re.match(r\\\\\\\'^\\\\\\\\d+-\\\\\\\\d+$\\\\\\\', term):\\\\n            lo, hi = [int(v) for v in term.split(\\\\\\\'-\\\\\\\')]\\\\n            if hi < lo or hi-lo > 10000:\\\\n                raise ValueError(\\\\\\\'Rango EXPNO invalido.\\\\\\\')\\\\n            result.extend(range(lo, hi+1))\\\\n        elif re.match(r\\\\\\\'^\\\\\\\\d+$\\\\\\\', term):\\\\n            result.append(int(term))\\\\n        else:\\\\n            raise ValueError(\\\\\\\'EXPNO: use 10-32 o 10,12,14. Sin decimales.\\\\\\\')\\\\n    if not result or min(result) <= 0 or len(result) > 10000 or len(set(result)) != len(result):\\\\n        raise ValueError(\\\\\\\'EXPNO positivos, sin duplicados; maximo 10000.\\\\\\\')\\\\n    return result\\\\n\\\\ndef report_base():\\\\n    return os.path.join(os.path.expanduser(\\\\\\\'~\\\\\\\'), \\\\\\\'DiffAtOnce_DOSY\\\\\\\')\\\\n\\\\ndef new_report_dir(base, kind):\\\\n    base = os.path.abspath(os.path.expanduser(base))\\\\n    if not os.path.isdir(base):\\\\n        os.makedirs(base)\\\\n    stamp = datetime.datetime.utcnow().strftime(\\\\\\\'%Y%m%dT%H%M%SZ\\\\\\\')\\\\n    target = os.path.join(base, kind + \\\\\\\'_\\\\\\\' + stamp + \\\\\\\'_\\\\\\\' + uuid.uuid4().hex[:8])\\\\n    os.mkdir(target)\\\\n    return target\\\\n\\\\ndef write_text(path, text):\\\\n    if not isinstance(text, text_type):\\\\n        text = text.decode(\\\\\\\'utf-8\\\\\\\')\\\\n    with io.open(path, \\\\\\\'w\\\\\\\', encoding=\\\\\\\'utf-8\\\\\\\') as handle:\\\\n        handle.write(text)\\\\n\\\\ndef write_json(path, value):\\\\n    write_text(path, json.dumps(value, ensure_ascii=True, indent=2))\\\\n\\\\ndef csv_text(rows, keys):\\\\n    def quote(value):\\\\n        if value is None:\\\\n            return \\\\\\\'\\\\\\\'\\\\n        if isinstance(value, (list, dict)):\\\\n            value = json.dumps(value, ensure_ascii=True, sort_keys=True)\\\\n        text = text_type(value)\\\\n        return \\\\\\\'"\\\\\\\' + text.replace(\\\\\\\'"\\\\\\\', \\\\\\\'""\\\\\\\') + \\\\\\\'"\\\\\\\'\\\\n    return \\\\\\\'\\\\\\\\n\\\\\\\'.join([\\\\\\\',\\\\\\\'.join(quote(k) for k in keys)] +\\\\n                     [\\\\\\\',\\\\\\\'.join(quote(row.get(k)) for k in keys) for row in rows]) + \\\\\\\'\\\\\\\\n\\\\\\\'\\\\n\\\\ndef ramp_flow(api):\\\\n    current, folder = current_dataset(api)\\\\n    program = text_type(api.GETPAR(\\\\\\\'PULPROG\\\\\\\')).strip().strip(\\\\\\\'<>\\\\\\\')\\\\n    values = ask(api, \\\\\\\'DOSY: configurar rampas\\\\\\\',\\\\n        [\\\\\\\'EXPNO plantilla\\\\\\\', \\\\\\\'PROCNO plantilla\\\\\\\', \\\\\\\'Primer EXPNO destino\\\\\\\',\\\\n         \\\\\\\'Salto EXPNO entre rampas\\\\\\\', \\\\\\\'GPZ inicial (%)\\\\\\\', \\\\\\\'GPZ final (%)\\\\\\\',\\\\n         \\\\\\\'Paso GPZ (%)\\\\\\\', \\\\\\\'Indice GPZ\\\\\\\', \\\\\\\'DS en cada destino (vacio: heredar)\\\\\\\',\\\\n         \\\\\\\'Programa de pulsos esperado\\\\\\\'],\\\\n        [current[1], current[2], \\\\\\\'100\\\\\\\', \\\\\\\'100\\\\\\\', \\\\\\\'8\\\\\\\', \\\\\\\'96\\\\\\\', \\\\\\\'4\\\\\\\', \\\\\\\'6\\\\\\\', \\\\\\\'16\\\\\\\', program],\\\\n        \\\\\\\'Copias de parametros de una plantilla 1D. P30 y RG se conservan.\\\\\\\')\\\\n    if values is None:\\\\n        return\\\\n    times = ask(api, \\\\\\\'DOSY: tiempos de difusion\\\\\\\',\\\\n        [\\\\\\\'Parametro del tiempo (p. ej. D20)\\\\\\\', \\\\\\\'Valores en ms, separados por coma\\\\\\\',\\\\n         \\\\\\\'Numero de repeticiones si deja los tiempos vacios\\\\\\\', \\\\\\\'Carpeta de informes\\\\\\\'],\\\\n        [\\\\\\\'D20\\\\\\\', \\\\\\\'50,100,150\\\\\\\', \\\\\\\'3\\\\\\\', report_base()],\\\\n        \\\\\\\'Verifique el parametro en su secuencia. stebpgp1s1d: D20 = Delta grande; delta pequena = 2*P30.\\\\\\\')\\\\n    if times is None:\\\\n        return\\\\n    delays = [positive(v.strip(), \\\\\\\'Delta\\\\\\\')/1000.0 for v in times[1].split(\\\\\\\',\\\\\\\')] if times[1] else None\\\\n    cfg = {\\\\\\\'template_expno\\\\\\\': int(values[0]), \\\\\\\'template_procno\\\\\\\': int(values[1]),\\\\n           \\\\\\\'start_expno\\\\\\\': int(values[2]), \\\\\\\'experiment_stride\\\\\\\': int(values[3]),\\\\n           \\\\\\\'gradient_start_percent\\\\\\\': values[4], \\\\\\\'gradient_stop_percent\\\\\\\': values[5],\\\\n           \\\\\\\'gradient_step_percent\\\\\\\': values[6], \\\\\\\'gradient_index\\\\\\\': int(values[7]),\\\\n           \\\\\\\'dummy_scans\\\\\\\': int(values[8]) if values[8] else None,\\\\n           \\\\\\\'expected_pulse_program\\\\\\\': values[9], \\\\\\\'expected_dataset_name\\\\\\\': text_type(current[0]),\\\\n           \\\\\\\'delay_parameter\\\\\\\': times[0] if delays is not None else None,\\\\n           \\\\\\\'delay_values_s\\\\\\\': delays, \\\\\\\'ramp_count\\\\\\\': len(delays) if delays is not None else int(times[2]),\\\\n           \\\\\\\'delay_mapping_confirmed\\\\\\\': delays is not None, \\\\\\\'example_only\\\\\\\': False}\\\\n    plan = ramp.build_plan(cfg)\\\\n    plan[\\\\\\\'generator\\\\\\\'] = \\\\\\\'DiffAtOnce native TopSpin DOSY assistant 2.0\\\\\\\'\\\\n    summary = (\\\\\\\'Dataset: %s\\\\\\\\nPlantilla: %s/%s\\\\\\\\n%d rampas x %d puntos = %d experimentos\\\\\\\\n\\\\\\\'\\\\n               \\\\\\\'GPZ%d: %s a %s %%\\\\\\\\nTiempos D (s): %s\\\\\\\\nP30, RG y forma: heredados\\\\\\\\n\\\\\\\\n\\\\\\\') % (\\\\n               current[0], cfg[\\\\\\\'template_expno\\\\\\\'], cfg[\\\\\\\'template_procno\\\\\\\'], cfg[\\\\\\\'ramp_count\\\\\\\'],\\\\n               plan[\\\\\\\'points_per_ramp\\\\\\\'], plan[\\\\\\\'experiment_count\\\\\\\'], cfg[\\\\\\\'gradient_index\\\\\\\'],\\\\n               values[4], values[5], str(delays))\\\\n    table = csv_text(plan[\\\\\\\'rows\\\\\\\'], [\\\\\\\'ramp\\\\\\\',\\\\\\\'point\\\\\\\',\\\\\\\'expno\\\\\\\',\\\\\\\'gradient_percent\\\\\\\',\\\\\\\'delay_s\\\\\\\',\\\\\\\'dummy_scans\\\\\\\'])\\\\n    api.VIEWTEXT(\\\\\\\'Plan DOSY\\\\\\\', \\\\\\\'Revise destinos, tiempos y limites del equipo\\\\\\\', summary + table)\\\\n    choice = api.SELECT(\\\\\\\'Preparar DOSY\\\\\\\', summary +\\\\n        \\\\\\\'Crear confirma el mapeo del tiempo en la secuencia. Los destinos deben estar libres.\\\\\\\',\\\\n        [\\\\\\\'Crear experimentos\\\\\\\', \\\\\\\'Exportar plan solamente\\\\\\\', \\\\\\\'Cancelar\\\\\\\'])\\\\n    if choice not in (0, 1):\\\\n        return\\\\n    output = new_report_dir(times[3], \\\\\\\'rampas\\\\\\\')\\\\n    write_json(os.path.join(output,\\\\\\\'plan.json\\\\\\\'), plan)\\\\n    write_text(os.path.join(output,\\\\\\\'plan.csv\\\\\\\'), table)\\\\n    if choice == 0:\\\\n        try:\\\\n            created = ramp.prepare(api, plan)\\\\n        except Exception as error:\\\\n            write_json(os.path.join(output,\\\\\\\'preparacion.json\\\\\\\'), {\\\\\\\'status\\\\\\\':\\\\\\\'failed\\\\\\\',\\\\\\\'error\\\\\\\':str(error)})\\\\n            raise\\\\n        write_json(os.path.join(output,\\\\\\\'preparacion.json\\\\\\\'), {\\\\\\\'status\\\\\\\':\\\\\\\'prepared\\\\\\\',\\\\\\\'created\\\\\\\':created,\\\\\\\'acquisition_started\\\\\\\':False})\\\\n    api.MSG((\\\\\\\'Experimentos preparados. \\\\\\\' if choice == 0 else \\\\\\\'Plan exportado. \\\\\\\') +\\\\n            \\\\\\\'No se ha iniciado adquisicion.\\\\\\\\n\\\\\\\' + output)\\\\n\\\\ndef calibration_summary(result):\\\\n    return json.dumps({key:result.get(key) for key in\\\\n        (\\\\\\\'bruker_gradient_proposal\\\\\\\',\\\\\\\'fit\\\\\\\',\\\\\\\'calibration_profile\\\\\\\',\\\\\\\'temperature\\\\\\\',\\\\\\\'warnings\\\\\\\')}, ensure_ascii=True, indent=2)\\\\n\\\\ndef known_sequence_gradient(result):\\\\n    """Conditional physical G from the exact saved TBO pulse/shape model.\\\\n\\\\n    Never use the nominal installed constant. Different pulse/shape bytes do\\\\n    not inherit this sequence-specific model just because names are similar.\\\\n    """\\\\n    profile = result[\\\\\\\'calibration_profile\\\\\\\']\\\\n    scope = profile[\\\\\\\'scope\\\\\\\']\\\\n    if (scope.get(\\\\\\\'PULPROG\\\\\\\') != \\\\\\\'stebpgp1s1d\\\\\\\' or scope.get(\\\\\\\'NUC1\\\\\\\') != \\\\\\\'1H\\\\\\\' or\\\\n            scope.get(\\\\\\\'GPNAM6\\\\\\\') != \\\\\\\'SMSQ10.100\\\\\\\' or not TBO_MODEL_SOURCE_SHA256):\\\\n        return None\\\\n    for filename in (\\\\\\\'pulseprogram\\\\\\\',\\\\\\\'gpnam6\\\\\\\'):\\\\n        hashes = set(source[\\\\\\\'sha256\\\\\\\'] for source in TBO_PROFILE.get(\\\\\\\'sources\\\\\\\',[])\\\\n                     if source[\\\\\\\'path\\\\\\\'].replace(\\\\\\\'\\\\\\\\\\\\\\\\\\\\\\\',\\\\\\\'/\\\\\\\').split(\\\\\\\'/\\\\\\\')[-1] == filename)\\\\n        if len(hashes) != 1 or profile.get(\\\\\\\'saved_file_hashes\\\\\\\',{}).get(filename) not in hashes:\\\\n            return None\\\\n    delta = 2.0 * positive(scope[\\\\\\\'P30\\\\\\\'],\\\\\\\'P30\\\\\\\') * 1e-6\\\\n    effective_time = float(scope[\\\\\\\'D20\\\\\\\']) - .32525 * delta - float(scope[\\\\\\\'D16\\\\\\\']) / 2.0\\\\n    if effective_time <= 0:\\\\n        raise ValueError(\\\\\\\'Tiempo efectivo de la secuencia no positivo.\\\\\\\')\\\\n    gamma = 267.52218744e6\\\\n    shape_squared = float(TBO_PROFILE[\\\\\\\'shape_squared\\\\\\\'])\\\\n    b100 = positive(profile[\\\\\\\'b_at_100_percent_s_m2\\\\\\\'],\\\\\\\'b100\\\\\\\')\\\\n    coefficient_per_G2 = (gamma*delta)**2 * shape_squared * effective_time\\\\n    g = math.sqrt(b100/coefficient_per_G2)\\\\n    return {\\\\\\\'G_max_T_m\\\\\\\':g,\\\\\\\'G_max_G_cm\\\\\\\':g*100.0,\\\\\\\'G_max_G_mm\\\\\\\':g*10.0,\\\\n            \\\\\\\'G_relative_SE_regression_only\\\\\\\':result[\\\\\\\'fit\\\\\\\'][\\\\\\\'relative_slope_uncertainty_1sigma\\\\\\\']/2.0,\\\\n            \\\\\\\'model\\\\\\\':\\\\\\\'b100 = (gamma*Gmax*delta)^2 * shape_squared * (D20-0.32525*delta-D16/2)\\\\\\\',\\\\n            \\\\\\\'delta_s\\\\\\\':delta,\\\\\\\'effective_time_s\\\\\\\':effective_time,\\\\\\\'gamma_rad_s_T\\\\\\\':gamma,\\\\n            \\\\\\\'shape_squared\\\\\\\':shape_squared,\\\\\\\'source\\\\\\\':\\\\\\\'documented local sequence model; python/sequence_model.json\\\\\\\',\\\\n            \\\\\\\'model_source_sha256\\\\\\\':TBO_MODEL_SOURCE_SHA256,\\\\n            \\\\\\\'identity_check\\\\\\\':\\\\\\\'saved pulseprogram and gpnam6 SHA-256 equal the documented model identity\\\\\\\',\\\\n            \\\\\\\'status\\\\\\\':\\\\\\\'derived proposal; spectral/reference review required; not applied to Bruker\\\\\\\',\\\\n            \\\\\\\'uncertainty_scope\\\\\\\':\\\\\\\'regression only; excludes Dref, temperature and pulse-model uncertainty\\\\\\\'}\\\\n\\\\ndef escape_html(value):\\\\n    return text_type(value).replace(\\\\\\\'&\\\\\\\',\\\\\\\'&amp;\\\\\\\').replace(\\\\\\\'<\\\\\\\',\\\\\\\'&lt;\\\\\\\').replace(\\\\\\\'>\\\\\\\',\\\\\\\'&gt;\\\\\\\').replace(\\\\\\\'"\\\\\\\',\\\\\\\'&quot;\\\\\\\')\\\\n\\\\ndef fit_svg(result, residual=False):\\\\n    rows, fit = result[\\\\\\\'rows\\\\\\\'], result[\\\\\\\'fit\\\\\\\']\\\\n    x = [r[\\\\\\\'x_gradient_fraction_squared\\\\\\\'] for r in rows]\\\\n    y = [r[\\\\\\\'residual_log\\\\\\\'] if residual else r[\\\\\\\'log_relative_intensity\\\\\\\'] for r in rows]\\\\n    lo, hi = min(y+[0.0]), max(y+[0.0])\\\\n    if not residual:\\\\n        model = [fit[\\\\\\\'intercept_log_I_over_Imax\\\\\\\']+fit[\\\\\\\'slope\\\\\\\']*v for v in x]\\\\n        lo, hi = min(y+model+[0.0]), max(y+model+[0.0])\\\\n    span = max(hi-lo, 1e-6)\\\\n    lo, hi = lo-.12*span, hi+.12*span\\\\n    xmax = max(max(x)*1.04, .01)\\\\n    sx = lambda v: 90+v/xmax*880\\\\n    sy = lambda v: 310-(v-lo)/(hi-lo)*240\\\\n    title = \\\\\\\'Residuos del ajuste\\\\\\\' if residual else \\\\\\\'Atenuacion e intercepto libre\\\\\\\'\\\\n    svg = \\\\\\\'<svg viewBox="0 0 1040 390" role="img" aria-label="\\\\\\\'+title+\\\\\\\'"><text x="90" y="32" font-size="23">\\\\\\\'+title+\\\\\\\'</text>\\\\\\\'\\\\n    svg += \\\\\\\'<path d="M90 70V310H970" fill="none" stroke="#122e40"/>\\\\\\\'\\\\n    for j in range(5):\\\\n        xx, yy = xmax*j/4, lo+(hi-lo)*j/4\\\\n        svg += \\\\\\\'<text x="%.2f" y="338" text-anchor="middle">%.3g</text>\\\\\\\' % (sx(xx),xx)\\\\n        svg += \\\\\\\'<text x="80" y="%.2f" text-anchor="end">%.3g</text>\\\\\\\' % (sy(yy)+5,yy)\\\\n    if residual:\\\\n        svg += \\\\\\\'<path d="M90 %.3fH970" stroke="#b56525" stroke-dasharray="5 5"/>\\\\\\\' % sy(0)\\\\n    else:\\\\n        pairs = sorted(zip(x,model))\\\\n        svg += \\\\\\\'<polyline points="\\\\\\\'+ \\\\\\\' \\\\\\\'.join(\\\\\\\'%.3f,%.3f\\\\\\\'%(sx(a),sy(b)) for a,b in pairs)+\\\\\\\'" fill="none" stroke="#b56525" stroke-width="3"/>\\\\\\\'\\\\n    for xx,yy in zip(x,y):\\\\n        svg += \\\\\\\'<circle cx="%.3f" cy="%.3f" r="4" fill="#087e98"/>\\\\\\\'%(sx(xx),sy(yy))\\\\n    ylabel = \\\\\\\'Residuo logaritmico\\\\\\\' if residual else \\\\\\\'ln(I / Imax)\\\\\\\'\\\\n    return svg + \\\\\\\'<text x="510" y="377" text-anchor="middle">(GPZ / 100)^2</text><text transform="translate(23 210) rotate(-90)" text-anchor="middle">\\\\\\\'+ylabel+\\\\\\\'</text></svg>\\\\\\\'\\\\n\\\\ndef make_report(result):\\\\n    # The JSON retains all precision and diagnostics; charts are a display of those values.\\\\n    rows = result[\\\\\\\'rows\\\\\\\']\\\\n    body = \\\\\\\'<!doctype html><meta charset="utf-8"><title>Calibracion DOSY</title>\\\\\\\'\\\\n    body += \\\\\\\'<style>body{font:17px system-ui;background:#f5f2ea;color:#122e40;max-width:1100px;margin:40px auto}svg{background:white;width:100%;margin:12px 0}pre{white-space:pre-wrap}table{border-collapse:collapse;font-size:14px}td,th{border:1px solid #bcc;padding:8px}</style>\\\\\\\'\\\\n    body += \\\\\\\'<h1>Calibracion DOSY del patron</h1><p>Integral firmada en una region ppm fija. Ajuste con intercepto libre. La escala empirica se limita a las condiciones registradas.</p>\\\\\\\'\\\\n    body += fit_svg(result) + fit_svg(result,True)\\\\n    body += \\\\\\\'<pre>\\\\\\\' + escape_html(calibration_summary(result)) + \\\\\\\'</pre>\\\\\\\'\\\\n    keys = [\\\\\\\'expno\\\\\\\',\\\\\\\'gradient_percent\\\\\\\',\\\\\\\'integral\\\\\\\',\\\\\\\'predicted_integral\\\\\\\',\\\\\\\'residual_log\\\\\\\']\\\\n    body += \\\\\\\'<table><tr>\\\\\\\' + \\\\\\\'\\\\\\\'.join(\\\\\\\'<th>\\\\\\\'+escape_html(k)+\\\\\\\'</th>\\\\\\\' for k in keys) + \\\\\\\'</tr>\\\\\\\'\\\\n    for row in rows:\\\\n        body += \\\\\\\'<tr>\\\\\\\' + \\\\\\\'\\\\\\\'.join(\\\\\\\'<td>\\\\\\\'+escape_html(row.get(k,\\\\\\\'\\\\\\\'))+\\\\\\\'</td>\\\\\\\' for k in keys) + \\\\\\\'</tr>\\\\\\\'\\\\n    return body + \\\\\\\'</table>\\\\\\\'\\\\n\\\\ndef open_report(path):\\\\n    try:\\\\n        from java.awt import Desktop\\\\n        from java.io import File\\\\n        Desktop.getDesktop().browse(File(path).toURI())\\\\n    except ImportError:\\\\n        import webbrowser\\\\n        webbrowser.open(\\\\\\\'file://\\\\\\\' + os.path.abspath(path).replace(\\\\\\\'\\\\\\\\\\\\\\\\\\\\\\\',\\\\\\\'/\\\\\\\'))\\\\n\\\\ndef calibration_flow(api):\\\\n    current, folder = current_dataset(api)\\\\n    selection = ask(api, \\\\\\\'Calibracion DOSY: serie del patron\\\\\\\',\\\\n        [\\\\\\\'EXPNO (p. ej. 10-32 o 100,102,104)\\\\\\\', \\\\\\\'PROCNO\\\\\\\', \\\\\\\'Limite ppm inferior\\\\\\\',\\\\n         \\\\\\\'Limite ppm superior\\\\\\\', \\\\\\\'Carpeta de informes\\\\\\\'],\\\\n        [\\\\\\\'\\\\\\\', current[2], \\\\\\\'\\\\\\\', \\\\\\\'\\\\\\\', report_base()],\\\\n        \\\\\\\'Use la region del patron de ESTA muestra. Espectros procesados 1D con fase, linea base y escala comparables.\\\\\\\')\\\\n    if selection is None:\\\\n        return\\\\n    references = ask(api, \\\\\\\'Calibracion DOSY: referencia y temperatura\\\\\\\',\\\\n        [\\\\\\\'Patron, disolvente y fuente del D de referencia\\\\\\\',\\\\n         \\\\\\\'D de referencia a esa T (en 10^-9 m2/s)\\\\\\\', \\\\\\\'Temperatura de referencia (K)\\\\\\\',\\\\n         \\\\\\\'Maxima variacion TE de la serie (K)\\\\\\\', \\\\\\\'Maxima diferencia de cada TE frente a T referencia (K)\\\\\\\'],\\\\n        [\\\\\\\'\\\\\\\', \\\\\\\'\\\\\\\', \\\\\\\'\\\\\\\', \\\\\\\'0.5\\\\\\\', \\\\\\\'0.5\\\\\\\'],\\\\n        \\\\\\\'D de referencia obligatorio. 1.902 para HDO/D2O corresponde a 298.15 K; no se impone a otra temperatura.\\\\\\\')\\\\n    if references is None:\\\\n        return\\\\n    result = calibration.analyze_series(folder, parse_expnos(selection[0]), int(selection[1]),\\\\n        float(selection[2]), float(selection[3]), positive(references[1],\\\\\\\'D referencia\\\\\\\'),\\\\n        positive(references[2],\\\\\\\'T referencia\\\\\\\'), references[0],\\\\n        max_temperature_span_K=positive(references[3],\\\\\\\'Variacion TE\\\\\\\'),\\\\n        max_reference_temperature_difference_K=positive(references[4],\\\\\\\'Diferencia T\\\\\\\'))\\\\n    result[\\\\\\\'bruker_gradient_proposal\\\\\\\'] = known_sequence_gradient(result)\\\\n    output = new_report_dir(selection[4], \\\\\\\'calibracion\\\\\\\')\\\\n    write_json(os.path.join(output,\\\\\\\'calibracion.json\\\\\\\'),result)\\\\n    keys = sorted(set(k for row in result[\\\\\\\'rows\\\\\\\'] for k in row))\\\\n    write_text(os.path.join(output,\\\\\\\'atenuacion_residuos.csv\\\\\\\'),csv_text(result[\\\\\\\'rows\\\\\\\'],keys))\\\\n    report = os.path.join(output,\\\\\\\'informe.html\\\\\\\')\\\\n    write_text(report,make_report(result))\\\\n    api.VIEWTEXT(\\\\\\\'Calibracion DOSY\\\\\\\', \\\\\\\'Resultado y diagnosticos\\\\\\\',\\\\n        calibration_summary(result) + \\\\\\\'\\\\\\\\n\\\\\\\\nGuardado en: \\\\\\\' + output +\\\\n        \\\\\\\'\\\\\\\\nLa escala b/GPZ^2 es experimental. No cambia la constante global de Bruker. No se incluye una calibracion experimental de ejemplo aplicable a su equipo.\\\\\\\')\\\\n    proposal = result[\\\\\\\'bruker_gradient_proposal\\\\\\\']\\\\n    buttons = [\\\\\\\'Abrir informe\\\\\\\',\\\\\\\'Abrir gradpar\\\\\\\',\\\\\\\'Cerrar\\\\\\\'] if proposal else [\\\\\\\'Abrir informe\\\\\\\',\\\\\\\'Cerrar\\\\\\\']\\\\n    message = output\\\\n    if proposal:\\\\n        message += \\\\\\\'\\\\\\\\n\\\\\\\\nG propuesta: %.9g G/cm = %.9g G/mm\\\\\\\' % (proposal[\\\\\\\'G_max_G_cm\\\\\\\'],proposal[\\\\\\\'G_max_G_mm\\\\\\\'])\\\\n    choice = api.SELECT(\\\\\\\'Resultado DOSY\\\\\\\', message, buttons)\\\\n    if choice == 0:\\\\n        open_report(report)\\\\n    elif proposal and choice == 1:\\\\n        api.XCMD(\\\\\\\'gradpar\\\\\\\',wait=api.WAIT_TILL_DONE)\\\\n        api.MSG(\\\\\\\'G propuesta: %.9g G/cm = %.9g G/mm.\\\\\\\\nRevise el ajuste y la referencia antes de introducirla. Guardado por sonda: setpre > File > Write.\\\\\\\' % (proposal[\\\\\\\'G_max_G_cm\\\\\\\'],proposal[\\\\\\\'G_max_G_mm\\\\\\\']))\\\\n\\\\ndef gradient_flow(api):\\\\n    values = ask(api,\\\\\\\'Calibracion Bruker: constante de gradiente\\\\\\\',\\\\n        [\\\\\\\'G anterior usada al calcular D medido\\\\\\\', \\\\\\\'Unidad G (G/cm o G/mm)\\\\\\\',\\\\n         \\\\\\\'D medido con esa G (10^-9 m2/s)\\\\\\\', \\\\\\\'D referencia (10^-9 m2/s)\\\\\\\',\\\\n         \\\\\\\'T referencia (K)\\\\\\\', \\\\\\\'Patron, disolvente y fuente\\\\\\\', \\\\\\\'Carpeta de informes\\\\\\\'],\\\\n        [\\\\\\\'\\\\\\\', \\\\\\\'G/cm\\\\\\\', \\\\\\\'\\\\\\\', \\\\\\\'\\\\\\\', \\\\\\\'\\\\\\\', \\\\\\\'\\\\\\\', report_base()],\\\\n        \\\\\\\'Introduzca valores del mismo analisis. No se carga el gradiente nominal de la instalacion.\\\\\\\')\\\\n    if values is None:\\\\n        return\\\\n    if values[1] not in (\\\\\\\'G/cm\\\\\\\',\\\\\\\'G/mm\\\\\\\'):\\\\n        raise ValueError(\\\\\\\'Unidad G admitida: G/cm o G/mm, sin conversion implicita.\\\\\\\')\\\\n    gold, dm, dr = [positive(values[n], \\\\\\\'Dato de calibracion\\\\\\\') for n in (0,2,3)]\\\\n    temp = positive(values[4], \\\\\\\'T referencia\\\\\\\')\\\\n    if not values[5]:\\\\n        raise ValueError(\\\\\\\'Indique patron, disolvente y fuente.\\\\\\\')\\\\n    gnew = calibration.gradient_correction(gold,dm,dr,values[1])[\\\\\\\'new_gradient_constant\\\\\\\']\\\\n    result = {\\\\\\\'G_old\\\\\\\':gold,\\\\\\\'G_new\\\\\\\':gnew,\\\\\\\'G_unit\\\\\\\':values[1], \\\\\\\'D_measured_1e9\\\\\\\':dm,\\\\n              \\\\\\\'D_reference_1e9\\\\\\\':dr,\\\\\\\'temperature_K\\\\\\\':temp,\\\\\\\'reference\\\\\\\':values[5],\\\\n              \\\\\\\'formula\\\\\\\':\\\\\\\'G_new = G_old * sqrt(D_measured / D_reference)\\\\\\\',\\\\n              \\\\\\\'instrument_calibration_modified\\\\\\\':False}\\\\n    output = new_report_dir(values[6], \\\\\\\'constante_gradiente\\\\\\\')\\\\n    write_json(os.path.join(output,\\\\\\\'constante_propuesta.json\\\\\\\'),result)\\\\n    text = \\\\\\\'G nueva = %.9g %s\\\\\\\\n\\\\\\\\n%s\\\\\\\\n\\\\\\\\nGuardado: %s\\\\\\\\nEl valor calculado debe revisarse en el editor de la sonda.\\\\\\\' % (gnew,values[1],result[\\\\\\\'formula\\\\\\\'],output)\\\\n    if api.SELECT(\\\\\\\'Constante calculada\\\\\\\',text,[\\\\\\\'Abrir gradpar\\\\\\\',\\\\\\\'Cerrar\\\\\\\']) == 0:\\\\n        api.XCMD(\\\\\\\'gradpar\\\\\\\',wait=api.WAIT_TILL_DONE)\\\\n        api.MSG(\\\\\\\'Valor calculado: %.9g %s\\\\\\\\nPara guardar en la sonda: setpre > File > Write.\\\\\\\\nNo se han editado archivos globales desde este asistente.\\\\\\\\nSi cambia la constante, regenere difflist con xau dosy restore sobre una copia de analisis.\\\\\\\' % (gnew,values[1]))\\\\n\\\\ndef tbo_flow(api):\\\\n    keys = [\\\\\\\'id\\\\\\\',\\\\\\\'pulse_program\\\\\\\',\\\\\\\'gradient_shape\\\\\\\',\\\\\\\'shape_squared\\\\\\\',\\\\\\\'equation\\\\\\\',\\\\\\\'scope\\\\\\\',\\\\\\\'status\\\\\\\']\\\\n    text = json.dumps({key:TBO_PROFILE.get(key) for key in keys},ensure_ascii=True,indent=2)\\\\n    api.VIEWTEXT(\\\\\\\'Modelo de secuencia documentado / Documented sequence model\\\\\\\',\\\\\\\'sequence_model.json\\\\\\\',text +\\\\n        \\\\\\\'\\\\\\\\n\\\\\\\\nNo es una calibracion de su sonda. No contiene datos experimentales ni Dref predefinida.\\\\\\\\nNot a probe calibration. No experimental data or default Dref is included.\\\\\\\')\\\\n\\\\ndef main(api):\\\\n    try:\\\\n        action = api.SELECT(\\\\\\\'DiffAtOnce DOSY\\\\\\\',\\\\\\\'Rampas y calibracion desde TopSpin\\\\\\\',\\\\n            [\\\\\\\'Preparar rampas\\\\\\\',\\\\\\\'Calibrar con serie 1D\\\\\\\',\\\\\\\'Constante Bruker desde D medido\\\\\\\',\\\\\\\'Ver modelo de secuencia\\\\\\\',\\\\\\\'Salir\\\\\\\'])\\\\n        if action == 0:\\\\n            ramp_flow(api)\\\\n        elif action == 1:\\\\n            calibration_flow(api)\\\\n        elif action == 2:\\\\n            gradient_flow(api)\\\\n        elif action == 3:\\\\n            tbo_flow(api)\\\\n    except Exception as error:\\\\n        api.MSG(\\\\\\\'DOSY: \\\\\\\' + str(error))\\\\n\\\')\\n_ui = sys.modules["_dosy_console_ui"]\\n_ui.TBO_PROFILE = json.loads(\\\'{"id": "documented_stebpgp1s1d_SMSQ10_model_not_a_calibration", "pulse_program": "stebpgp1s1d", "gradient_shape": "SMSQ10.100", "shape_squared": 0.81, "equation": "b100 = (gamma*Gmax*delta)^2 * shape_squared * (D20 - 0.32525*delta - D16/2); delta=2*P30*1e-6; gamma=267.52218744e6 rad s^-1 T^-1", "scope": "Local historical sequence model retained for comparison only. Physical-G proposal requires exact saved pulseprogram and gpnam6 SHA-256, 1H, matching names, valid timings, spectral/reference review. Otherwise empirical b only. Not universal Stejskal-Tanner and not transferred to other sequences or timings by name alone.", "status": "documented model, not an experimental probe calibration or independent model validation", "sources": [{"path": "model_identity/pulseprogram", "sha256": "2219e346e7e422a68da6f4001857ddafc46c50b0e508f4c16d932c5870748dca"}, {"path": "model_identity/gpnam6", "sha256": "85b3e903dda475b283ac2575e55b69296c94725f946dd728c6965af98cf8e240"}], "model_source_sha256": "54bf401e220a90d6030a08da7f65548992f8d505910f5d2ad31fb5832081fd86"}\\\')\\n_ui.TBO_MODEL_SOURCE_SHA256 = \\\'54bf401e220a90d6030a08da7f65548992f8d505910f5d2ad31fb5832081fd86\\\'\\nif __name__ == "__main__":\\n    import TopCmds\\n    _ui.main(TopCmds)\\n\'.encode("utf-8"), "dosy_v2.py", "exec"), _base)\n_auto = types.ModuleType("_dosy_autorun")\nsys.modules["_dosy_autorun"] = _auto\nexec(compile(\'# -*- coding: utf-8 -*-\\n"""Native TopSpin Jython 2.7 calibration workflows. Hardware is opt-in in UI.\\n\\nUse a preconfigured 1D template. Copy parameters to NEW EXPNO only, acquire\\nsequentially with WAIT_TILL_DONE, process using fixed phase, then analyze.\\nNo global gradient or RF calibration setting is written by this script.\\n"""\\nfrom __future__ import division, unicode_literals\\nimport hashlib\\nimport io\\nimport json\\nimport math\\nimport os\\nimport sys\\n\\nimport _dosy_ramp_engine as engine\\nimport _dosy_calibration as calibration\\nimport _dosy_console_ui as legacy\\n\\ntry:\\n    text_type = unicode\\nexcept NameError:\\n    text_type = str\\n\\n\\ndef build_plan(current, mode, first_expno, values, expected_program):\\n    if mode not in ("p1", "gradient"):\\n        raise ValueError("Mode must be p1 or gradient")\\n    if len(current) != 4:\\n        raise ValueError("CURDATA must have four fields")\\n    current = [text_type(v) for v in current]\\n    dataset_dir = os.path.realpath(os.path.join(current[3], current[0]))\\n    if current[0] in (".", "..") or any(c in current[0] for c in ("/", "\\\\\\\\", "\\\\x00")):\\n        raise ValueError("Invalid dataset name")\\n    first = engine.integer(first_expno, "First EXPNO")\\n    template_expno = engine.integer(current[1], "Template EXPNO")\\n    procno = engine.integer(current[2], "PROCNO")\\n    if not 4 <= len(values) <= 500:\\n        raise ValueError("Provide 4..500 calibration points")\\n    numeric = [engine.number(v, "Sweep value", positive=(mode == "p1")) for v in values]\\n    if len(set(numeric)) != len(numeric) or sorted(numeric) != numeric:\\n        raise ValueError("Sweep values must be distinct and increasing")\\n    if mode == "gradient" and (numeric[0] < 0 or numeric[-1] > 100):\\n        raise ValueError("GPZ6 range must be inside 0..100 percent")\\n    if mode == "p1" and expected_program != "zg":\\n        raise ValueError("The P1 nutation workflow requires the simple zg pulse program")\\n    if not expected_program or not expected_program.strip():\\n        raise ValueError("Explicit pulse-program identity is required")\\n    rows = [{"point": i + 1, "expno": first + i, "procno": procno,\\n             "parameter": "P 1" if mode == "p1" else "GPZ 6", "value": value}\\n            for i, value in enumerate(numeric)]\\n    if any(r["expno"] == template_expno for r in rows):\\n        raise ValueError("A destination overlaps the template")\\n    return {"schema_version": 3, "mode": mode, "template": current,\\n            "dataset_dir": dataset_dir, "expected_program": expected_program,\\n            "rows": rows, "values": numeric, "unit": "us" if mode == "p1" else "percent",\\n            "processing": "EFP with inherited PHC0/PHC1, no independent autophase or baseline fitting",\\n            "hardware_actions": "Only if operator chooses acquire: ZG(wait=WAIT_TILL_DONE), then EFP(wait=WAIT_TILL_DONE)",\\n            "global_calibration_modified": False}\\n\\n\\ndef paths_for(plan):\\n    return [os.path.join(plan["dataset_dir"], text_type(row["expno"])) for row in plan["rows"]]\\n\\n\\ndef dataset_for(plan, row):\\n    original = plan["template"]\\n    return [original[0], text_type(row["expno"]), text_type(row["procno"]), original[3]]\\n\\n\\ndef assert_dataset(api, expected):\\n    if not engine.equivalent_dataset(api.CURDATA(), expected):\\n        raise RuntimeError("Current dataset changed unexpectedly; workflow stopped")\\n\\n\\ndef verify_parameters(api, fixed, identities, row=None):\\n    for key, value in fixed.items():\\n        observed = engine.finite_number(api.GETPAR(key))\\n        if abs(observed - value) > 1e-9 * max(1.0, abs(value)):\\n            raise RuntimeError("Fixed template parameter changed: " + key)\\n    for key, value in identities.items():\\n        observed = text_type(api.GETPAR(key)).strip().strip("<>")\\n        if observed != value:\\n            raise RuntimeError("Template identity changed: " + key)\\n    if row is not None:\\n        observed = engine.finite_number(api.GETPAR(row["parameter"]))\\n        if abs(observed - row["value"]) > 1e-8 * max(1.0, abs(row["value"])):\\n            raise RuntimeError("Sweep value changed before acquisition: " + row["parameter"])\\n\\n\\ndef checked_command(api, method_name):\\n    """Conservative completion rule: synchronous documented command and rc=0.\\n\\n    Unknown/None command status stops the run. An on-instrument pilot must check\\n    acquisition return semantics for the installed TopSpin version; mere fid\\n    existence cannot distinguish an aborted acquisition from a completed one.\\n    """\\n    command = getattr(api, method_name)\\n    thread = command(wait=api.WAIT_TILL_DONE)\\n    if thread is None or not hasattr(thread, "getResult"):\\n        raise RuntimeError("%s returned no inspectable completion status" % method_name)\\n    code = thread.getResult()\\n    if code is None or text_type(code) not in ("0", "0.0"):\\n        raise RuntimeError("%s completion not confirmed (result=%s); no next experiment started" % (method_name, code))\\n    return {"command": method_name, "wait": "WAIT_TILL_DONE", "result": text_type(code)}\\n\\n\\ndef _snapshot_files(folder):\\n    result = {}\\n    for root, dirs, files in os.walk(folder):\\n        for name in files:\\n            path = os.path.join(root, name)\\n            with open(path, "rb") as handle:\\n                result[os.path.relpath(path, folder)] = hashlib.sha256(handle.read()).hexdigest()\\n    return result\\n\\n\\ndef run_plan(api, plan, output_dir, acquire=False):\\n    """Create a fresh series and optionally acquire/process it. Never resume.\\n\\n    A stopped run retains partial experiments and its journal. Reruns require new\\n    EXPNO, so neither acquired nor partially acquired data can be overwritten.\\n    """\\n    template = plan["template"]\\n    assert_dataset(api, template)\\n    targets = paths_for(plan)\\n    if not os.path.isdir(plan["dataset_dir"]):\\n        raise RuntimeError("Dataset directory does not exist")\\n    collisions = [p for p in targets if os.path.lexists(p)]\\n    if collisions:\\n        raise RuntimeError("Existing destinations; no experiment changed: " + ", ".join(collisions))\\n    if engine.finite_number(api.GETPAR("PARMODE")) != 0:\\n        raise RuntimeError("Only a 1D acquisition template is supported")\\n    program = text_type(api.GETPAR("PULPROG")).strip().strip("<>")\\n    if program != plan["expected_program"]:\\n        raise RuntimeError("PULPROG differs from the reviewed plan")\\n    fixed = {}\\n    for key in ("RG", "NS", "D 1", "PHC0", "PHC1", "LB"):\\n        fixed[key] = engine.finite_number(api.GETPAR(key))\\n    if fixed["RG"] <= 0 or fixed["NS"] < 1 or fixed["D 1"] <= 0:\\n        raise RuntimeError("Template requires positive RG, NS and D1")\\n    for key in ("P 1", "P 30", "D 20", "D 16"):\\n        if key != plan["rows"][0]["parameter"]:\\n            fixed[key] = engine.finite_number(api.GETPAR(key))\\n    power_keys = []\\n    for key in ("PL 1", "PLW 1", "PLdB 1", "SFO1", "O1"):\\n        try:\\n            value = api.GETPAR(key)\\n            if value is not None and text_type(value).strip():\\n                fixed[key] = engine.finite_number(value)\\n                if key.startswith("PL"):\\n                    power_keys.append(key)\\n        except Exception:\\n            pass\\n    if plan["mode"] == "p1" and not power_keys:\\n        raise RuntimeError("P1 calibration requires an inspectable channel-1 RF power parameter")\\n    identities = {"PULPROG": program}\\n    for key in ("NUC1", "PROBHD"):\\n        try:\\n            value = text_type(api.GETPAR(key)).strip().strip("<>")\\n            if value:\\n                identities[key] = value\\n        except Exception:\\n            pass\\n    template_dir = os.path.join(plan["dataset_dir"], template[1])\\n    before = _snapshot_files(template_dir)\\n    journal = {"plan": plan, "template_parameters": fixed, "template_identities": identities,\\n               "state": "preparing", "acquisition_requested": bool(acquire),\\n               "events": [], "global_calibration_modified": False}\\n    journal_path = os.path.join(output_dir, "execution.json")\\n    def save():\\n        legacy.write_json(journal_path, journal)\\n    save()\\n    error = None\\n    try:\\n        # Prepare the whole series first, so acquisition never starts after a\\n        # late destination collision or a failed parameter-copy preflight.\\n        for row, target in zip(plan["rows"], targets):\\n            if os.path.lexists(target):\\n                raise RuntimeError("Destination appeared after review: " + target)\\n            api.RE(template)\\n            assert_dataset(api, template)\\n            command = api.XCMD("wraparam " + text_type(row["expno"]), wait=api.WAIT_TILL_DONE)\\n            if command is not None and hasattr(command, "getResult") and command.getResult() == -1:\\n                raise RuntimeError("wraparam failed")\\n            if not os.path.isdir(target):\\n                raise RuntimeError("wraparam did not create the expected destination")\\n            engine.ensure_parameter_only(target)\\n            destination = dataset_for(plan, row)\\n            api.RE(destination)\\n            assert_dataset(api, destination)\\n            engine.set_and_verify(api, row["parameter"], row["value"])\\n            verify_parameters(api, fixed, identities, row)\\n            journal["events"].append({"expno": row["expno"], "stage": "parameters_prepared"})\\n            save()\\n        journal["state"] = "prepared"\\n        save()\\n        if acquire:\\n            for row, target in zip(plan["rows"], targets):\\n                engine.ensure_parameter_only(target)\\n                destination = dataset_for(plan, row)\\n                api.RE(destination)\\n                assert_dataset(api, destination)\\n                verify_parameters(api, fixed, identities, row)\\n                journal["state"] = "acquiring"\\n                journal["events"].append({"expno": row["expno"], "stage": "ZG_started"})\\n                save()\\n                result = checked_command(api, "ZG")\\n                assert_dataset(api, destination)\\n                fid = os.path.join(target, "fid")\\n                if not os.path.isfile(fid) or os.path.getsize(fid) == 0:\\n                    raise RuntimeError("ZG returned success but no nonempty 1D fid was written")\\n                journal["events"].append({"expno": row["expno"], "stage": "ZG_finished", "command": result})\\n                save()\\n                result = checked_command(api, "EFP")\\n                assert_dataset(api, destination)\\n                # The reader verifies full 1D layout, scaling and finite points.\\n                spectrum = calibration.read_processed_1r(target, row["procno"])\\n                journal["events"].append({"expno": row["expno"], "stage": "EFP_finished",\\n                                          "command": result, "sources": spectrum["sources"]})\\n                save()\\n            journal["state"] = "acquired_and_processed"\\n    except Exception as exc:\\n        error = text_type(exc)\\n        journal["state"] = "stopped"\\n        journal["error"] = error\\n    finally:\\n        try:\\n            api.RE(template)\\n            assert_dataset(api, template)\\n        except Exception as exc:\\n            error = (error + "; " if error else "") + "Could not restore original view: " + text_type(exc)\\n            journal["state"], journal["error"] = "stopped", error\\n        journal["template_preserved"] = _snapshot_files(template_dir) == before\\n        if not journal["template_preserved"]:\\n            error = (error + "; " if error else "") + "Template file hashes changed; investigate external writes"\\n            journal["state"], journal["error"] = "stopped", error\\n        save()\\n    if error:\\n        raise RuntimeError(error + "\\\\nPartial results retained; use NEW EXPNO for a new run.\\\\n" + journal_path)\\n    return journal\\n\\n\\ndef signed_integral(spectrum, low, high):\\n    """Nutation requires negative and zero areas; DOSY core intentionally does not."""\\n    low, high = engine.number(low, "ppm low"), engine.number(high, "ppm high")\\n    start, step, end = spectrum["ppm_start"], spectrum["ppm_step"], spectrum["ppm_end"]\\n    if not end <= low < high <= start:\\n        raise ValueError("Full integration window must lie inside the 1D spectrum")\\n    a, b = (start - high) / step, (start - low) / step\\n    if b - a < 2:\\n        raise ValueError("Integration region must span at least two intervals")\\n    values = spectrum["values"]\\n    def interp(index):\\n        i = int(math.floor(index))\\n        j = min(i + 1, len(values) - 1)\\n        return values[i] + (index - i) * (values[j] - values[i])\\n    points = [a] + [float(i) for i in range(int(math.floor(a)) + 1, int(math.ceil(b)))] + [b]\\n    return math.fsum((y - x) * (interp(x) + interp(y)) / 2 for x, y in zip(points[:-1], points[1:])) * step\\n\\n\\ndef fit_nutation(pulse_us, integrals, p90_min_us, p90_max_us):\\n    """Fit signed A*sin(pi*P1/(2*P90))+offset within an explicit search range."""\\n    t = [engine.number(v, "P1", positive=True) for v in pulse_us]\\n    y = [engine.number(v, "signed integral") for v in integrals]\\n    lo = engine.number(p90_min_us, "minimum P90", positive=True)\\n    hi = engine.number(p90_max_us, "maximum P90", positive=True)\\n    if len(t) != len(y) or len(t) < 9 or len(set(t)) < 9 or lo >= hi:\\n        raise ValueError("Nutation fit needs >=9 distinct pulse lengths and a valid bounded P90 search")\\n    scale = max(abs(v) for v in y)\\n    if scale == 0 or min(y) >= -.02 * scale or max(y) <= .1 * scale:\\n        raise ValueError("Signed nutation must include positive and negative signal; verify fixed phase and sweep span")\\n    mean_y = math.fsum(y) / len(y)\\n    def model(p90):\\n        s = [math.sin(math.pi * value / (2 * p90)) for value in t]\\n        mean_s = math.fsum(s) / len(s)\\n        denominator = math.fsum((v - mean_s) ** 2 for v in s)\\n        if denominator <= 1e-20:\\n            return float("inf"), 0., 0., []\\n        amplitude = math.fsum((a - mean_s) * (b - mean_y) for a, b in zip(s, y)) / denominator\\n        offset = mean_y - amplitude * mean_s\\n        predicted = [amplitude * a + offset for a in s]\\n        error = math.fsum((a - b) ** 2 for a, b in zip(y, predicted))\\n        return (error if amplitude > 0 else float("inf")), amplitude, offset, predicted\\n    grid = [lo + (hi - lo) * i / 400 for i in range(401)]\\n    scores = [model(v)[0] for v in grid]\\n    best = min(range(len(grid)), key=lambda i: scores[i])\\n    if best in (0, 400) or math.isinf(scores[best]):\\n        raise ValueError("P90 optimum is at the search boundary or phase is incompatible")\\n    left, right = grid[best - 1], grid[best + 1]\\n    golden = (math.sqrt(5.) - 1) / 2\\n    for unused in range(70):\\n        a, b = right - golden * (right - left), left + golden * (right - left)\\n        if model(a)[0] <= model(b)[0]:\\n            right = b\\n        else:\\n            left = a\\n    p90 = (left + right) / 2\\n    sse, amplitude, offset, predicted = model(p90)\\n    if min(t) > .75 * p90 or max(t) < 2.1 * p90:\\n        raise ValueError("Sweep must sample the initial rise and extend beyond the first inversion")\\n    sst = math.fsum((v - mean_y) ** 2 for v in y)\\n    return {"P90_us": p90, "P180_us": 2 * p90, "model": "I(P1)=A*sin(pi*P1/(2*P90))+offset",\\n            "pulse_us": t, "integrals": y, "predicted_integrals": predicted,\\n            "residuals": [a - b for a, b in zip(y, predicted)], "R2": 1 - sse / sst,\\n            "amplitude": amplitude, "offset": offset, "search_range_us": [lo, hi],\\n            "uncertainty": "Not quantified; RF inhomogeneity, relaxation, off-resonance and integration can bias the ideal sine fit",\\n            "status": "proposal at the template RF power; inspect nutation and residuals before application",\\n            "written_to_instrument": False}\\n\\n\\ndef analyze_p1(plan, low, high, p90_min, p90_max):\\n    if plan["mode"] != "p1":\\n        raise ValueError("Expected P1 plan")\\n    areas, sources, baseline, temperatures = [], [], None, []\\n    for row, folder in zip(plan["rows"], paths_for(plan)):\\n        spectrum = calibration.read_processed_1r(folder, row["procno"])\\n        acquisition = spectrum["acquisition"]\\n        actual = float(calibration._required(acquisition, "P", 1))\\n        if abs(actual - row["value"]) > 1e-8 * max(1, row["value"]):\\n            raise ValueError("Acquired P1 does not match the sweep plan")\\n        if calibration._required(acquisition, "PULPROG") != "zg":\\n            raise ValueError("Acquired P1 series does not use zg")\\n        stable = dict((key, calibration._required(acquisition, key)) for key in\\n                      ("PULPROG", "PROBHD", "NUC1", "RG", "NS"))\\n        for key in ("D", "P", "PL", "PLW", "PLdB", "GPX", "GPY", "GPZ", "GPNAM"):\\n            if key in acquisition:\\n                stable[key] = list(acquisition[key])\\n                if key == "P" and len(stable[key]) > 1:\\n                    stable[key][1] = None\\n        # Native files use arrays; test fixtures or exported JCAMP may also use\\n        # scalar aliases. Capture those without excluding any RF power field.\\n        for key in acquisition:\\n            if key != "P1" and (key.startswith("PL") or\\n                    (key[:1] in ("P", "D") and key[1:].isdigit())):\\n                stable[key] = acquisition[key]\\n        stable["processing"] = dict((key, spectrum["processing"].get(key)) for key in\\n                                    ("SI", "SF", "SW_p", "OFFSET", "PHC0", "PHC1", "LB", "BC_mod"))\\n        if baseline is None:\\n            baseline = stable\\n        elif baseline != stable:\\n            raise ValueError("P1 series changed RF power, delays, acquisition or fixed processing parameters")\\n        temperatures.append(engine.number(calibration._required(acquisition, "TE"), "TE", positive=True))\\n        areas.append(signed_integral(spectrum, float(low), float(high)))\\n        sources.extend(spectrum["sources"])\\n    result = fit_nutation(plan["values"], areas, p90_min, p90_max)\\n    result.update({"sources": sources, "ppm_region": [float(low), float(high)], "plan": plan,\\n                   "scope": baseline, "TE_min_K": min(temperatures), "TE_max_K": max(temperatures)})\\n    return result\\n\\n\\ndef flow(api, mode):\\n    current, folder = legacy.current_dataset(api)\\n    program = text_type(api.GETPAR("PULPROG")).strip().strip("<>")\\n    if mode == "p1" and program != "zg":\\n        raise ValueError("Abra una plantilla 1D zg, ajustada y con fase correcta, para calibrar P1.")\\n    if mode == "p1":\\n        nominal = legacy.positive(api.GETPAR("P 1"), "P1 de plantilla")\\n        values_default = ",".join("%.6g" % (nominal * (.2 + .2 * i)) for i in range(22))\\n    else:\\n        nominal = None\\n        values_default = ",".join(text_type(v) for v in range(8, 97, 4))\\n    dialog = legacy.ask(api, "DOSY v3: " + ("nutacion P1" if mode == "p1" else "calibracion de gradientes"),\\n        ["Primer EXPNO NUEVO", "P1 en us, separados por coma" if mode == "p1" else "GPZ6 en %, separados por coma",\\n         "Limite ppm inferior", "Limite ppm superior", "Carpeta de informes"],\\n        ["500" if mode == "p1" else "600", values_default, "", "", legacy.report_base()],\\n        "Plantilla actual: " + program + ". Potencia RF, RG, NS, D1 y fase se heredan. Revise la relajacion y los limites de la sonda.")\\n    if dialog is None:\\n        return\\n    values = [engine.number(v.strip(), "Valor") for v in dialog[1].split(",")]\\n    plan = build_plan(current, mode, int(dialog[0]), values, program)\\n    low, high = engine.number(dialog[2], "ppm inferior"), engine.number(dialog[3], "ppm superior")\\n    if low >= high:\\n        raise ValueError("Limites ppm no validos")\\n    if mode == "p1":\\n        details = legacy.ask(api, "P1: intervalo del ajuste",\\n            ["P90 minimo (us)", "P90 maximo (us)"], [nominal * .25, nominal * 1.5],\\n            "El P1 actual puede ser 180 grados: NO se supone que sea P90. Edite el intervalo. Fase fija, sin APK por punto.")\\n    else:\\n        details = legacy.ask(api, "DOSY: referencia del patron",\\n            ["Patron, disolvente y fuente", "Dref a esa T (10^-9 m2/s)", "T referencia (K)",\\n             "Maximo intervalo TE (K)", "Maxima diferencia TE frente Tref (K)"], ["", "", "", ".5", ".5"],\\n            "D20/P30 se conservan. Esta adquisicion calibra UNA condicion de tiempos.")\\n    if details is None:\\n        return\\n    if mode == "p1":\\n        pmin, pmax = legacy.positive(details[0], "P90 minimo"), legacy.positive(details[1], "P90 maximo")\\n        if pmin >= pmax or len(values) < 9:\\n            raise ValueError("Se requieren >=9 puntos y P90 minimo < P90 maximo")\\n    else:\\n        if not details[0].strip():\\n            raise ValueError("Indique patron, disolvente y fuente")\\n        for index, label in ((1, "Dref"), (2, "Tref"), (3, "Variacion TE"), (4, "Diferencia TE")):\\n            legacy.positive(details[index], label)\\n    plan["analysis"] = {"ppm_low": low, "ppm_high": high, "reference_fields": details}\\n    summary = json.dumps(plan, ensure_ascii=True, indent=2)\\n    api.VIEWTEXT("Plan de calibracion v3", "Destinos nuevos; no se modifican originales ni constantes globales", summary)\\n    choice = api.SELECT("Accion", "Revise la sonda, muestra, potencia RF, temperatura, D1, RG y fase antes de adquirir.",\\n                        ["Exportar plan", "Preparar sin adquirir", "Preparar, adquirir y analizar", "Cancelar"])\\n    if choice not in (0, 1, 2):\\n        return\\n    if choice == 2 and api.SELECT("Iniciar adquisicion ahora",\\n            "Se ejecutaran %s adquisiciones ZG en EXPNO nuevos y EFP con fase fija.\\\\n"\\n            "Confirme que la muestra, sonda, potencia RF, limites del barrido, relajacion y temperatura estan preparados." % len(plan["rows"]),\\n            ["Iniciar serie", "Cancelar"]) != 0:\\n        return\\n    output = legacy.new_report_dir(dialog[4], "v3_" + mode)\\n    legacy.write_json(os.path.join(output, "plan.json"), plan)\\n    if choice == 0:\\n        api.MSG("Plan exportado: " + output)\\n        return\\n    run_plan(api, plan, output, acquire=(choice == 2))\\n    if choice == 1:\\n        api.MSG("Parametros preparados. No se ha iniciado adquisicion.\\\\n" + output)\\n        return\\n    if mode == "p1":\\n        result = analyze_p1(plan, low, high, float(details[0]), float(details[1]))\\n        legacy.write_json(os.path.join(output, "p1_propuesta.json"), result)\\n        legacy.write_text(os.path.join(output, "nutacion.csv"), legacy.csv_text(\\n            [{"P1_us": t, "integral": y, "predicha": p, "residuo": r} for t, y, p, r in\\n             zip(result["pulse_us"], result["integrals"], result["predicted_integrals"], result["residuals"])],\\n            ["P1_us", "integral", "predicha", "residuo"]))\\n        api.VIEWTEXT("Propuesta P1", "Potencia RF heredada; revisar antes de aplicar",\\n                     "P90 = %.7g us; P180 = %.7g us; R2 = %.7g\\\\n%s" % (result["P90_us"], result["P180_us"], result["R2"], output))\\n    else:\\n        result = calibration.analyze_series(folder, [r["expno"] for r in plan["rows"]], current[2],\\n            low, high, float(details[1]), float(details[2]), details[0], float(details[3]), float(details[4]))\\n        result["bruker_gradient_proposal"] = legacy.known_sequence_gradient(result)\\n        legacy.write_json(os.path.join(output, "calibracion.json"), result)\\n        legacy.write_text(os.path.join(output, "informe.html"), legacy.make_report(result))\\n        keys = ["expno", "gradient_percent", "integral", "predicted_integral", "residual_log"]\\n        legacy.write_text(os.path.join(output, "atenuacion_residuos.csv"), legacy.csv_text(result["rows"], keys))\\n        api.VIEWTEXT("Calibracion DOSY v3", "Ajuste y residuos", legacy.calibration_summary(result) + "\\\\n" + output)\\n\\n\\ndef main(api):\\n    try:\\n        action = api.SELECT("DiffAtOnce DOSY v3", "Automatizacion desde TopSpin",\\n            ["Calibrar P1: barrido de nutacion", "Calibrar DOSY: adquirir rampa del patron", "Asistente anterior: rampas y analisis", "Salir"])\\n        if action in (0, 1):\\n            flow(api, "p1" if action == 0 else "gradient")\\n        elif action == 2:\\n            legacy.main(api)\\n    except Exception as exc:\\n        api.MSG("Calibracion detenida: " + text_type(exc))\\n\'.encode("utf-8"), "dosy_autorun.py", "exec"), _auto.__dict__)\nif __name__ == "__main__":\n    import TopCmds\n    _auto.main(TopCmds)\n'.encode("utf-8"),"calibration_core.py","exec"),_base)
